/// Map pure-math haircut errors to CloberError codes. Used by every
/// haircut ix that calls into `matcher::haircut`.
fn map_haircut_error(e: matcher::haircut::HaircutError) -> anchor_lang::error::Error {
    use matcher::haircut::HaircutError::*;
    match e {
        Overflow => error!(CloberError::ArithmeticOverflow),
        Underflow => error!(CloberError::ArithmeticUnderflow),
        InvertedWindow => error!(CloberError::HaircutInvertedWindow),
        WindowTooLarge => error!(CloberError::HaircutWindowTooLarge),
        ZeroGain => error!(CloberError::HaircutZeroGain),
    }
}

/// Shared runtime gate used by all three oracle-update ix.
///
/// When `envelope_config` is `Some(...)`:
///   1. If `last_observed_slot == 0` (first observation), the gate is
///      skipped (no prior price to compare). `now_slot`/`new_price`
///      are recorded as the new baseline.
///   2. Otherwise: compute `dt = now_slot - last_observed_slot`, call
///      `gate_price_move(last_price, new_price, dt,
///      max_price_move_bps_per_slot)`. Reject → bubble up.
///   3. On success: record `(now_slot, new_price)` and bump
///      `gate_passes`.
///
/// When `envelope_config` is `None`: no-op (legacy behavior).
fn gate_oracle_update<'info>(
    envelope_config: Option<&mut Box<Account<'info, extended_state::MarketEnvelopeConfigAccount>>>,
    new_price_ticks: u64,
    now_slot: u64,
) -> Result<()> {
    let Some(cfg) = envelope_config else {
        return Ok(());
    };
    if cfg.last_observed_slot == 0 {
        // First observation — seed and skip gate.
        cfg.last_observed_slot = now_slot;
        cfg.last_observed_price_ticks = new_price_ticks;
        cfg.gate_passes = cfg.gate_passes.saturating_add(1);
        return Ok(());
    }
    let dt = now_slot.saturating_sub(cfg.last_observed_slot);
    // Same-slot updates are allowed iff the new price equals the old
    // one (no movement). gate_price_move rejects strict zero dt.
    if dt == 0 {
        if new_price_ticks == cfg.last_observed_price_ticks {
            return Ok(());
        }
        cfg.gate_rejects = cfg.gate_rejects.saturating_add(1);
        return Err(error!(CloberError::EnvelopeSameSlotMove));
    }
    // The per-slot cap is only PROVEN sound over a window
    // of `max_accrual_dt_slots` (see `prove_envelope`). Admitting the raw dt
    // after a crank gap (e.g. a stalled ER) would let a single update jump by
    // cap * dt, far beyond the proven per-window loss budget — a position
    // healthy before the gap could breach maintenance in one step. Clamp the
    // accrual window so the admitted move saturates at the proven budget; a
    // larger genuine move must be applied over multiple cranks.
    let dt = if cfg.max_accrual_dt_slots > 0 {
        dt.min(cfg.max_accrual_dt_slots)
    } else {
        dt
    };
    let last_price = cfg.last_observed_price_ticks;
    matcher::envelope::gate_price_move(
        last_price,
        new_price_ticks,
        dt,
        cfg.max_price_move_bps_per_slot,
    )
    .map_err(|e| {
        cfg.gate_rejects = cfg.gate_rejects.saturating_add(1);
        map_envelope_error(e)
    })?;
    cfg.last_observed_slot = now_slot;
    cfg.last_observed_price_ticks = new_price_ticks;
    cfg.gate_passes = cfg.gate_passes.saturating_add(1);
    Ok(())
}

/// Map pure-math envelope errors to CloberError codes.
fn map_envelope_error(e: matcher::envelope::EnvelopeError) -> anchor_lang::error::Error {
    use matcher::envelope::EnvelopeError::*;
    match e {
        PriceCapZero | PriceCapTooLarge => error!(CloberError::EnvelopePriceCapInvalid),
        AccrualDtZero | AccrualDtTooLarge => error!(CloberError::EnvelopeAccrualWindowInvalid),
        FundingCapTooLarge => error!(CloberError::EnvelopeFundingCapInvalid),
        MaintenanceZero | MaintenanceTooLarge => error!(CloberError::EnvelopeMaintenanceInvalid),
        LiqFeeTooLarge => error!(CloberError::EnvelopeLiqFeeInvalid),
        Overflow => error!(CloberError::ArithmeticOverflow),
        SameSlotMove => error!(CloberError::EnvelopeSameSlotMove),
        PriceMoveExceedsCap => error!(CloberError::EnvelopePriceMoveExceedsCap),
        EnvelopeViolated { .. } => error!(CloberError::EnvelopeViolated),
    }
}

