/// Accept a pending transfer. Auth is the `new_authority`
/// signer matching the stored `pending_authority` (context constraint) — NOT the
/// current market authority. Closes the pending account (rent → new_authority).
#[derive(Accounts)]
pub struct AcceptAuthorityTransfer<'info> {
    #[account(mut)]
    pub new_authority: Signer<'info>,
    #[account(
        mut,
        seeds = [MarketAccount::SEED, market.base_mint.as_ref(), market.quote_mint.as_ref()],
        bump = market.bump,
    )]
    // Boxed: MarketAccount deserialized onto the stack tips this context's 4 KB
    // BPF frame once it grows (3.1 haircut fields). Box moves it to the heap.
    pub market: Box<Account<'info, MarketAccount>>,
    #[account(
        mut,
        close = new_authority,
        seeds = [state::MarketPendingAuthorityAccount::SEED, market.key().as_ref()],
        bump = pending.bump,
        constraint = pending.market == market.key() @ CloberError::WrongMarket,
        constraint = pending.pending_authority == new_authority.key() @ CloberError::Unauthorized,
    )]
    pub pending: Account<'info, state::MarketPendingAuthorityAccount>,
}

/// Cancel a pending transfer (authority-only). Closes the
