/// Dual-source health price (P-LIQ-1/2) for the cross-margin risk walk and ADL.
/// Returns the price to feed `assess_margin` for `market`, using the SAME proven
/// selection as the single-position `liquidate_position`. FRESH mark ⇒
/// worse-of(mark, oracle) for the position's direction (a fresh oracle move
/// immediately tips the position, and the EMA-lagging mark can't hide adverse
/// liquidity); previously this path used the mark ALONE, so the portfolio/ADL
/// surface could carry a position under-margined by up to the mark↔oracle gap
/// versus the single-position surface. STALE mark ⇒ oracle ALONE (a stalled ER
/// froze the fill stream), and only a configured + published + fresh oracle —
/// else no trustworthy price ⇒ error, so the caller refuses to liquidate
/// (fail-safe).
/// The oracle is folded into the worse-of only when it is trustworthy for
/// health (configured + published, and required-fresh below); otherwise it is
/// passed as 0 so the worse-of prices off the mark alone. `is_long` is the
/// position's direction in `market`.
/// 4.4: open interest on a position's SIDE, for the OI-crowding maintenance surcharge on a
/// `RiskMarketSnap`. With `oi_mmr_slope == 0` (default) the surcharge is 0 regardless, so
/// every wired site is byte-identical to the pre-4.4 behaviour until a market opts in.
#[inline]
fn oi_side_lots(market: &MarketAccount, is_long: bool) -> u64 {
    if is_long {
        market.oi_long_lots
    } else {
        market.oi_short_lots
    }
}

fn effective_health_mark(
    market: &MarketAccount,
    now_unix: u64,
    current_slot: u64,
    is_long: bool,
) -> Result<u64> {
    let mark_t = market.mark_price_ticks;
    let oracle_t = market.oracle_price_ticks;
    let oracle_max_age = market.params.oracle_staleness_max_seconds as u64;
    let published = market.oracle_published_at_unix_seconds;

    // A configured + published oracle folded into the worse-of MUST be fresh —
    // else refuse rather than price health off a possibly-stale oracle.
    if oracle_max_age > 0 && published > 0 {
        require!(
            now_unix.saturating_sub(published) <= oracle_max_age,
            CloberError::OracleTooStale
        );
    }
    let mark_stale = market.last_mark_update_slot == 0
        || current_slot.saturating_sub(market.last_mark_update_slot)
            > constants::MARK_STALENESS_MAX_SLOTS;
    // When the mark is stale the oracle is the SOLE price ⇒ it must be
    // configured + published (freshness already enforced above).
    if mark_stale {
        require!(oracle_max_age > 0, CloberError::MarkTooStale);
        require!(published > 0, CloberError::MarkTooStale);
    }
    // Only a trustworthy oracle is folded in; otherwise pass 0 (worse-of prices
    // off the mark alone).
    let oracle_for_health = if oracle_max_age > 0 && published > 0 {
        oracle_t
    } else {
        0
    };
    match matcher::liquidation::health_price_with_staleness(
        mark_t,
        oracle_for_health,
        mark_stale,
        is_long,
    ) {
        Some((hp, _)) => Ok(hp),
        None => Err(error!(CloberError::MarkTooStale)),
    }
}

/// 4.5-era stack fix: load + validate ONE basket-N leg. Extracted from the
/// `place_basket_order_n` loop and marked `#[inline(never)]` so the sizeable
/// `MarketAccount` / `PositionAccount` deserialized here live in this helper's
/// BPF frame rather than the (already large) handler's — the handler stays under
/// the 4 KB limit as `MarketParams` grows. Logic is byte-for-byte the original
/// loop body: owner checks, deserialize, market-key dedup, leg-intake + cap
/// gates, canonical-position-PDA binding, trader/market checks, then push.
#[inline(never)]
#[allow(clippy::too_many_arguments)]
fn basket_n_load_leg(
    m_ai: &AccountInfo<'_>,
    book_ai: &AccountInfo<'_>,
    pos_ai: &AccountInfo<'_>,
    leg: &BasketLeg,
    program_id: &Pubkey,
    trader_key: Pubkey,
    trader_state_key: Pubkey,
    lp_exposure: &LiquidityPoolAccount,
    markets: &mut Vec<MarketAccount>,
    positions: &mut Vec<state::PositionAccount>,
    market_keys: &mut Vec<Pubkey>,
) -> Result<()> {
    require_keys_eq!(*m_ai.owner, *program_id, CloberError::Unauthorized);
    // book_ai owner is also this program (PDA we own). Disc check happens inside
    // MarketBookHandle::from_account_data on inject.
    require_keys_eq!(*book_ai.owner, *program_id, CloberError::Unauthorized);
    require_keys_eq!(*pos_ai.owner, *program_id, CloberError::Unauthorized);

    let market: MarketAccount = MarketAccount::try_deserialize(&mut &m_ai.try_borrow_data()?[..])?;
    let position: state::PositionAccount =
        state::PositionAccount::try_deserialize(&mut &pos_ai.try_borrow_data()?[..])?;

    for prev in market_keys.iter() {
        require!(*prev != m_ai.key(), CloberError::OutOfRange);
    }
    market_keys.push(m_ai.key());

    validate_leg_intake(&market, leg)?;
    check_caps_for_leg(&market, &position, lp_exposure, leg)?;

    // Bind this leg's position to the CANONICAL PDA for (leg market, signing
    // trader_state) — without it an attacker passes a small/empty position so the
    // margin lattice sees ~no exposure while the fill accrues to their real one.
    require_canonical_position_pda(&m_ai.key(), &trader_state_key, &pos_ai.key(), program_id)?;

    if position.size_lots > 0 {
        require!(position.trader == trader_key, CloberError::WrongTrader);
        require!(position.market == m_ai.key(), CloberError::WrongMarket);
    }

    markets.push(market);
    positions.push(position);
    Ok(())
}

/// Validate per-leg intake gates: status, size/price floors, tick alignment.
/// Skips per-market margin check — basket margin runs across both legs.
fn validate_leg_intake(market: &MarketAccount, leg: &BasketLeg) -> Result<()> {
    require!(leg.size_lots > 0, CloberError::ZeroSize);
    require!(leg.limit_ticks > 0, CloberError::ZeroPrice);
    require!(leg.side <= 1, CloberError::OutOfRange);
    require!(
        market.status == MarketStatus::Active as u8
            || market.status == MarketStatus::PostOnly as u8,
        CloberError::OutOfRange
    );
    require!(
        leg.size_lots >= market.params.min_base_lots,
        CloberError::SizeBelowMinLot
    );
    require!(
        leg.limit_ticks % market.params.tick_size == 0,
        CloberError::PriceNotOnTick
    );
    require!(
        leg.size_lots <= LP_SEQ_RESERVED_OFFSET,
        CloberError::OutOfRange
    );
    Ok(())
}

/// Apply absolute and capital-relative position caps for a single basket leg.
fn check_caps_for_leg(
    market: &MarketAccount,
    position: &state::PositionAccount,
    lp: &LiquidityPoolAccount,
    leg: &BasketLeg,
) -> Result<()> {
    let cap = market.params.max_position_lots_per_trader;
    if cap > 0 {
        let new_size = position.size_lots.saturating_add(leg.size_lots);
        require!(new_size <= cap, CloberError::PositionSizeCapExceeded);
    }
    let ratio_cap = market.params.max_position_ratio_bps;
    if ratio_cap > 0 && lp.total_capital_quote_lots > 0 {
        let cap_quote_lots = (lp.total_capital_quote_lots as u128)
            .saturating_mul(ratio_cap as u128)
            / (constants::BPS_DENOM as u128);
        let new_size = position.size_lots.saturating_add(leg.size_lots);
        let new_notional = (new_size as u128)
            .saturating_mul(leg.limit_ticks as u128)
            .saturating_mul(market.params.tick_size as u128);
        require!(
            new_notional <= cap_quote_lots,
            CloberError::PositionSizeCapExceeded
        );
    }
    Ok(())
}

/// Project a position's post-leg state for the cross-market margin check.
/// Returns None if the resulting projected position is still empty.
fn project_post_leg(
    position: &state::PositionAccount,
    leg: &BasketLeg,
    market: &MarketAccount,
    market_key: Pubkey,
    trader: Pubkey,
) -> Result<Option<RiskPosSnap>> {
    // If no current position, the projected state assumes the leg fills
    // entirely as a new position at limit_ticks.
    if position.size_lots == 0 {
        return Ok(Some(RiskPosSnap {
            market: market_key,
            side: if leg.side == 0 {
                Side::Long
            } else {
                Side::Short
            },
            size_lots: leg.size_lots,
            entry_price: Ticks(leg.limit_ticks),
            cum_funding_index_at_entry: market.cum_funding_index,
            collateral_quote_lots: position.collateral_quote_lots,
        }));
    }
    require!(position.trader == trader, CloberError::WrongTrader);
    require!(position.market == market_key, CloberError::WrongMarket);
    // Worst-case projection: same-side adds, opposite-side has the leg's
    // limit price as the worst-case fill (size grows for margin assessment
    // even if it would actually reduce on cross). Conservative.
    let projected_size = if position.side == leg.side {
        position.size_lots.saturating_add(leg.size_lots)
    } else {
        // Opposite side: in worst case the leg fully fills and adds to
        // the existing same-side, AKA a flip. Approximate post-state as
        // |existing - leg_size|; if leg ≥ existing, we'd be on the leg's
        // side after fill.
        leg.size_lots.abs_diff(position.size_lots)
    };
    let projected_side = if position.side == leg.side {
        position.side
    } else if leg.size_lots > position.size_lots {
        leg.side
    } else {
        position.side
    };
    Ok(Some(RiskPosSnap {
        market: market_key,
        side: if projected_side == 0 {
            Side::Long
        } else {
            Side::Short
        },
        size_lots: projected_size,
        entry_price: Ticks(position.entry_price_ticks),
        cum_funding_index_at_entry: position.cum_funding_index(),
        collateral_quote_lots: position.collateral_quote_lots,
    }))
}

#[repr(u8)]
pub enum MarketStatus {
    Inactive = 0,
    Active = 1,
    PostOnly = 2,
    Paused = 3,
    Closed = 4,
    // Wind-down: order intake is open but every order is forced reduce-only, so
    // positions can only be closed, never opened or grown. Authority-only (it is
    // deliberately outside the guardian's monotonic restrict ladder). Numbered
    // last to keep the existing on-chain status values stable.
    CloseOnly = 5,
}

/// Inject one basket leg into a hypertree-backed market_book PDA.
/// Used by `place_basket_order`. Returns (assigned_seq, node_index)
/// for the inserted RestingOrder.
///
/// The market_book account is passed as `UncheckedAccount` (typed in the
/// caller's ctx). This helper takes a borrow of its data, writes the
/// new RestingOrder via the hypertree handle, and returns.
fn inject_leg_into_hypertree(
    market_book: &UncheckedAccount<'_>,
    market_key: Pubkey,
    trader_key: Pubkey,
    leg: &BasketLeg,
    now_slot: u64,
    sub_index: u8,
) -> Result<(u64, hypertree::DataIndex)> {
    let mut book_data = market_book.try_borrow_mut_data()?;
    let mut handle = book_state::MarketBookHandle::from_account_data(&mut book_data)?;
    require!(
        handle.header.market_pubkey == market_key,
        CloberError::WrongMarket
    );
    let next_seq = handle
        .header
        .order_seq_counter
        .checked_add(1)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    require!(
        next_seq < LP_SEQ_RESERVED_OFFSET,
        CloberError::OutOfRange
    );
    handle.header.order_seq_counter = next_seq;

    let side_is_bid = leg.side == 0;
    let order = book_state::RestingOrder {
        order_id: book_state::encode_order_id(leg.limit_ticks, next_seq, side_is_bid),
        seq: next_seq,
        price_ticks: leg.limit_ticks,
        size_lots: leg.size_lots,
        expires_at_slot: 0,
        trader: trader_key,
        last_valid_slot: u32::try_from(now_slot).unwrap_or(u32::MAX),
        side: leg.side,
        order_type: 0, // limit
        flags: if leg.post_only { 0b0000_0001 } else { 0 },
        sub_index,
    };
    let idx = if side_is_bid {
        handle.insert_bid(order)?
    } else {
        handle.insert_ask(order)?
    };
    Ok((next_seq, idx))
}

/// AccountInfo variant for `place_basket_order_n`, where leg market_books
/// arrive via `remaining_accounts` (untyped). Same insertion contract.
fn inject_leg_into_hypertree_unchecked(
    market_book_ai: &AccountInfo<'_>,
    market_key: Pubkey,
    trader_key: Pubkey,
    leg: &BasketLeg,
    now_slot: u64,
    sub_index: u8,
) -> Result<()> {
    let mut book_data = market_book_ai.try_borrow_mut_data()?;
    let mut handle = book_state::MarketBookHandle::from_account_data(&mut book_data)?;
    require!(
        handle.header.market_pubkey == market_key,
        CloberError::WrongMarket
    );
    let next_seq = handle
        .header
        .order_seq_counter
        .checked_add(1)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    require!(
        next_seq < LP_SEQ_RESERVED_OFFSET,
        CloberError::OutOfRange
    );
    handle.header.order_seq_counter = next_seq;

    let side_is_bid = leg.side == 0;
    let order = book_state::RestingOrder {
        order_id: book_state::encode_order_id(leg.limit_ticks, next_seq, side_is_bid),
        seq: next_seq,
        price_ticks: leg.limit_ticks,
        size_lots: leg.size_lots,
        expires_at_slot: 0,
        trader: trader_key,
        last_valid_slot: u32::try_from(now_slot).unwrap_or(u32::MAX),
        side: leg.side,
        order_type: 0,
        flags: if leg.post_only { 0b0000_0001 } else { 0 },
        sub_index,
    };
    if side_is_bid {
        handle.insert_bid(order)?;
    } else {
        handle.insert_ask(order)?;
    }
    Ok(())
}

/// Validate a fee-tier table for `init_fee_tiers /
/// update_fee_tiers`. Enforces:
///   • Non-empty + ≤ MAX_FEE_TIERS
///   • Sorted ascending by `min_volume_quote_lots`
///   • Tier 0 has `min_volume == 0` (default tier required)
///   • Monotone improving: taker fee ↘, maker rebate ↗ as volume rises
///   • All bps within MAX_FEE_TIER_BPS
///   • volume_window_slots is non-zero (would otherwise treat every
///     fill as a window expiry → permanent reset)
fn validate_fee_tiers(volume_window_slots: u64, tiers: &[state::FeeTier]) -> Result<()> {
    require!(volume_window_slots > 0, CloberError::OutOfRange);
    require!(!tiers.is_empty(), CloberError::OutOfRange);
    require!(
        tiers.len() <= state::MAX_FEE_TIERS,
        CloberError::OutOfRange
    );
    require!(
        tiers[0].min_volume_quote_lots == 0,
        CloberError::OutOfRange
    );

    let mut prev_min: Option<u64> = None;
    let mut prev_taker: Option<u32> = None;
    let mut prev_maker: Option<i32> = None;
    for t in tiers {
        require!(
            t.taker_fee_bps <= constants::MAX_FEE_TIER_BPS,
            CloberError::OutOfRange
        );
        // Maker rebate is SIGNED (i32). Cap by absolute value — same
        // typo guard as taker fee, applied to either sign of rebate.
        require!(
            t.maker_rebate_bps.unsigned_abs() <= constants::MAX_FEE_TIER_BPS,
            CloberError::OutOfRange
        );
        if let Some(p) = prev_min {
            require!(t.min_volume_quote_lots > p, CloberError::OutOfRange);
        }
        if let Some(pt) = prev_taker {
            require!(t.taker_fee_bps <= pt, CloberError::OutOfRange);
        }
        if let Some(pm) = prev_maker {
            // Monotone non-decreasing — higher tier never has WORSE
            // maker treatment than a lower tier (signed comparison
            // means -10 < 0 < +5, so retail → MM progression works).
            require!(t.maker_rebate_bps >= pm, CloberError::OutOfRange);
        }
        prev_min = Some(t.min_volume_quote_lots);
        prev_taker = Some(t.taker_fee_bps);
        prev_maker = Some(t.maker_rebate_bps);
    }
    Ok(())
}

/// Pure helper that returns the index of the highest
/// tier the trader's `volume` qualifies for (0-indexed). Empty pairs →
/// returns 0 (no tier change ever fires). Used to detect tier-upgrade
/// boundary crossings inside `apply_fill` so we can emit a
/// `TraderTierUpgradedEvent` only on actual change.
fn tier_index_for_volume(pairs: &[(u64, i32, u32)], volume: u64) -> u8 {
    let mut idx: u8 = 0;
    for (i, (min_vol, _, _)) in pairs.iter().enumerate() {
        if volume >= *min_vol {
            idx = i as u8;
        } else {
            break;
        }
    }
    idx
}

/// Credit a trader's rolling-window volume + re-anchor the
/// window if it has expired (or was never seeded). Called on every
/// economic fill from `apply_fill` for both maker and taker.
///
/// Window-expiry semantics: when `now - window_start >
/// DEFAULT_VOLUME_WINDOW_SLOTS`, we RESET volume to 0 and re-anchor
/// the window at `now` BEFORE crediting the new fill's notional. This
/// semantics: "rolling window resets, current trade starts the new
/// window" pattern. `view_trader_effective_tier` mirrors this — for
/// reads it honors the authority-configured window from FeeTiersAccount
/// (which can be tighter or wider than the default).
fn credit_volume_for_tier<'info>(
    state: &mut AccountLoader<'info, TraderStateAccount>,
    notional_quote_lots: u64,
    now_slot: u64,
) -> Result<()> {
    let mut state = state.load_mut()?;
    let elapsed = now_slot.saturating_sub(state.volume_window_start_slot);
    if state.volume_window_start_slot == 0 || elapsed > constants::DEFAULT_VOLUME_WINDOW_SLOTS {
        state.volume_30d_quote_lots = 0;
        state.volume_window_start_slot = now_slot;
    }
    state.volume_30d_quote_lots = state
        .volume_30d_quote_lots
        .saturating_add(notional_quote_lots);
    Ok(())
}

/// Map a `RestingOrder.order_type` byte to the matcher's OrderType.
/// Preserves the matcher's FIFO priority weighting (limits behind
/// takers, takers behind liquidations, ADL highest).
///
/// Unknown bytes default to Limit — defensive; an attacker writing a
/// junk value in the order_type byte gets the lowest-priority bucket.
pub fn order_type_byte_to_matcher(b: u8) -> matcher::order::OrderType {
    use matcher::order::OrderType;
    match b {
        0 => OrderType::Limit,
        1 => OrderType::Taker,
        2 => OrderType::LpVirtual,
        3 => OrderType::Liquidation,
        4 => OrderType::Adl,
        _ => OrderType::Limit,
    }
}

/// Realized volatility (stdev of relative returns) over a clearing-price
/// window, expressed in bps. Pure-integer; uses isqrt.
fn realized_vol_bps_from_window(prices: &[u64; MARK_HISTORY_LEN], count: u8) -> u32 {
    let n = (count as usize).min(prices.len());
    if n < 2 {
        return 0;
    }
    // returns_bps[i] = (p[i+1] - p[i]) * 10_000 / p[i]
    let mut returns: [i64; MARK_HISTORY_LEN] = [0; MARK_HISTORY_LEN];
    let mut returns_n: usize = 0;
    let mut sum: i64 = 0;
    for i in 0..(n - 1) {
        let p0 = prices[i] as i128;
        let p1 = prices[i + 1] as i128;
        if p0 <= 0 {
            continue;
        }
        let r_bps = ((p1 - p0) * 10_000) / p0;
        // clamp to i64 range (returns of ±100% × 10_000 = ±1_000_000 fits trivially)
        let r = if r_bps > i64::MAX as i128 {
            i64::MAX
        } else if r_bps < i64::MIN as i128 {
            i64::MIN
        } else {
            r_bps as i64
        };
        returns[returns_n] = r;
        returns_n += 1;
        sum = sum.saturating_add(r);
    }
    if returns_n == 0 {
        return 0;
    }
    let mean = sum / returns_n as i64;
    let mut var_sum: i128 = 0;
    for r in returns.iter().take(returns_n) {
        let d = (*r - mean) as i128;
        var_sum = var_sum.saturating_add(d * d);
    }
    let variance = var_sum / returns_n as i128;
    let stdev = (variance.max(0) as u128).isqrt() as u64;
    // Cap at 10_000 bps (= 100%) — a plausible upper bound on per-batch return stdev.
    stdev.min(10_000) as u32
}

/// Read LP per-market entry side+size for a market. Returns (side, size).
/// Side 255 = empty slot.
fn lp_market_pre_state(lp: &LiquidityPoolAccount, market: Pubkey) -> (u8, u64) {
    for entry in lp.per_market.iter() {
        if entry.side != 255 && entry.market == market {
            return (entry.side, entry.size_lots);
        }
    }
    (255, 0)
}

/// Apply a fill against the LP's per-market entry. Mirrors
/// `apply_fill_to_position` semantics on a `LpMarketExposure` slot.
fn apply_fill_to_lp_market(
    lp: &mut LiquidityPoolAccount,
    market: Pubkey,
    fill_side: Side,
    fill_size_lots: u64,
    fill_price_ticks: u64,
    tick_size: u64,
) -> Result<()> {
    // Find existing entry or first empty slot.
    let mut entry_idx: Option<usize> = None;
    let mut empty_idx: Option<usize> = None;
    for (i, entry) in lp.per_market.iter().enumerate() {
        if entry.side != 255 && entry.market == market {
            entry_idx = Some(i);
            break;
        }
        if entry.side == 255 && empty_idx.is_none() {
            empty_idx = Some(i);
        }
    }

    let idx = match entry_idx {
        Some(i) => i,
        None => {
            let i = empty_idx.ok_or_else(|| error!(CloberError::BufferFull))?;
            lp.per_market[i] = state::LpMarketExposure {
                market,
                side: fill_side as u8,
                size_lots: fill_size_lots,
                entry_price_ticks: fill_price_ticks,
            };
            lp.markets_count = lp.markets_count.saturating_add(1);
            return Ok(());
        }
    };

    // Existing pool position: settle through the SAME Kani-proven core as trader
    // fills (`matcher::position_math`) — the pool and a trader provably use
    // byte-identical open/stack-VWAP/reduce-flip + H-1 PnL math. This handler
    // adds only the LP-specific plumbing: aggregate realized PnL (saturating, as
    // before — LP carries it on `lp.realized_pnl`, not per-market) and the slot
    // lifecycle (free the slot + decrement `markets_count` on a full close). The
    // pool has no funding anchor, so the core's `reset_funding` flag is moot.
    use matcher::position_math as pm;
    let cur = pm::Pos {
        side: lp.per_market[idx].side,
        size_lots: lp.per_market[idx].size_lots,
        entry_ticks: lp.per_market[idx].entry_price_ticks,
    };
    let outcome = pm::apply_fill(
        cur,
        fill_side as u8,
        fill_size_lots,
        fill_price_ticks,
        tick_size,
    )
    .map_err(|e| match e {
        pm::PosMathError::Overflow => error!(CloberError::ArithmeticOverflow),
        pm::PosMathError::Underflow => error!(CloberError::ArithmeticUnderflow),
        pm::PosMathError::DivByZero => error!(CloberError::DivisionByZero),
    })?;
    lp.realized_pnl = lp
        .realized_pnl
        .saturating_add(outcome.realized_pnl_quote_lots);
    let slot = &mut lp.per_market[idx];
    if outcome.pos.size_lots == 0 {
        // Full close → free the slot (mirrors the prior close-to-zero path).
        slot.side = 255;
        slot.size_lots = 0;
        slot.entry_price_ticks = 0;
        lp.markets_count = lp.markets_count.saturating_sub(1);
    } else {
        slot.side = outcome.pos.side;
        slot.size_lots = outcome.pos.size_lots;
        slot.entry_price_ticks = outcome.pos.entry_ticks;
    }
    Ok(())
}

/// Update OI counters for a single trader's position transition.
fn update_oi(
    market: &mut MarketAccount,
    pre_side: u8,
    pre_size: u64,
    post_side: u8,
    post_size: u64,
) -> Result<()> {
    if pre_size > 0 {
        if pre_side == 0 {
            market.oi_long_lots = market.oi_long_lots.saturating_sub(pre_size);
        } else {
            market.oi_short_lots = market.oi_short_lots.saturating_sub(pre_size);
        }
    }
    if post_size > 0 {
        if post_side == 0 {
            market.oi_long_lots = market
                .oi_long_lots
                .checked_add(post_size)
                .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
        } else {
            market.oi_short_lots = market
                .oi_short_lots
                .checked_add(post_size)
                .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
        }
    }
    Ok(())
}

/// Single-position margin-threshold check. Cheap (no portfolio walk):
/// computes equity = collateral + unrealized_pnl(pos, mark) and required
/// = pos_notional × mmr_bps / 10_000, then emits a
/// MarginThresholdCrossedEvent on threshold crossings (250%, 200%, 125%).
/// Off-chain UIs subscribe and push pre-liquidation alerts.
/// Silent when required == 0 or numbers don't fit.
fn emit_margin_threshold_if_crossed(
    trader: Pubkey,
    market: Pubkey,
    pos: &state::PositionAccount,
    mark_ticks: u64,
    tick_size: u64,
    mmr_bps: u32,
    collateral_quote_lots: u64,
) {
    if pos.size_lots == 0 || mark_ticks == 0 || mmr_bps == 0 {
        return;
    }
    let notional_u128 = (pos.size_lots as u128)
        .saturating_mul(mark_ticks as u128)
        .saturating_mul(tick_size as u128);
    let required = notional_u128.saturating_mul(mmr_bps as u128) / constants::BPS_DENOM as u128;
    if required == 0 {
        return;
    }
    // Unrealized PnL: (mark - entry) × size × ±1
    let pnl_per_lot_ticks = (mark_ticks as i128) - (pos.entry_price_ticks as i128);
    let sign: i128 = if pos.side == 0 { 1 } else { -1 };
    let unrealized = sign
        .saturating_mul(pos.size_lots as i128)
        .saturating_mul(pnl_per_lot_ticks)
        .saturating_mul(tick_size as i128);
    let equity_signed = (collateral_quote_lots as i128).saturating_add(unrealized);
    if equity_signed <= 0 {
        emit!(MarginThresholdCrossedEvent {
            trader,
            market,
            level: 2,
            equity_to_mmr_bps: 0,
        });
        return;
    }
    let ratio_bps_u128 =
        (equity_signed as u128).saturating_mul(constants::BPS_DENOM as u128) / required;
    let ratio_bps: u32 = if ratio_bps_u128 > u32::MAX as u128 {
        u32::MAX
    } else {
        ratio_bps_u128 as u32
    };
    // Threshold ladder. Higher ratio = healthier. Critical first wins.
    let level: Option<u8> = if ratio_bps < 12_500 {
        Some(2) // critical (< 125% of MMR)
    } else if ratio_bps < 20_000 {
        Some(1) // warn (< 200%)
    } else if ratio_bps < 25_000 {
        Some(0) // caution (< 250%)
    } else {
        None
    };
    if let Some(level) = level {
        emit!(MarginThresholdCrossedEvent {
            trader,
            market,
            level,
            equity_to_mmr_bps: ratio_bps,
        });
    }
}

/// §3.2 P4 / RISK-M2 + RISK-1: settle ONE position's accrued funding against the
/// current mark, routing collateral (isolated→position bucket, cross→trader pool)
/// and the solvency Residual exactly as `settle_funding` does, then advance the
/// position's funding anchor. Returns the signed amount owed (+ pays / − receives)
/// for the caller to record/emit.
///
/// IDEMPOTENT: once the anchor equals `market_cum_funding_index` the funding delta
/// is 0 — so calling this in `apply_fill` (to charge funding on a position BEFORE a
/// closing fill drops it) never double-charges a position the sequencer also
/// settled via `settle_funding`. `settle_funding` and `apply_fill` share this one
/// implementation, so the routing + Residual accounting can never diverge.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum FundingRouteErr {
    Overflow,
}

/// Pure RISK-1 funding-routing core (Kani-proven, see `funding_routing_proofs`).
/// Given the signed funding `owed` (+ pays / − receives), the chosen collateral
/// bucket, and the current solvency Residual, returns the updated
/// `(collateral, residual)`.
///
/// CONSERVATION (the RISK-1 invariant): the change in collateral equals the
/// NEGATIVE change in the Residual — `Δcollateral == −Δresidual` — so funding can
/// never mint or burn protocol collateral. BOTH directions clamp to availability:
/// a payment is clamped to the bucket's collateral, and a receipt is clamped to
/// the solvency Residual it is paid out of. The clamped remainder is absorbed as
/// the funding anchor advances (the payer under-pays / the receiver is haircut),
/// exactly the socialized treatment the residual/haircut engine already applies
/// to a shortfall. Clamping — rather than reverting on an exhausted Residual —
/// is REQUIRED for liveness: `route_funding` runs at the strict-FIFO ring head
/// inside `apply_fill`, so a revert there would wedge every later settlement on
/// the market (a settlement-DoS), and every other value-shortfall leg (taker/
/// maker fee, bad-debt) is already capped, not reverting.
fn route_funding(
    owed: i64,
    collateral: u64,
    residual: u128,
) -> core::result::Result<(u64, u128), FundingRouteErr> {
    if owed > 0 {
        let paid = (owed as u64).min(collateral);
        let new_residual = residual
            .checked_add(paid as u128)
            .ok_or(FundingRouteErr::Overflow)?;
        Ok((collateral - paid, new_residual)) // paid ≤ collateral ⇒ no underflow
    } else if owed < 0 {
        // Pay the receipt out of the Residual, clamped to what it can back.
        let received = owed.unsigned_abs() as u128;
        let applied = received.min(residual);
        let new_collateral = collateral
            .checked_add(applied as u64) // applied ≤ |owed| ≤ i64::MAX ⇒ fits u64
            .ok_or(FundingRouteErr::Overflow)?;
        Ok((new_collateral, residual - applied)) // applied ≤ residual ⇒ no underflow
    } else {
        Ok((collateral, residual))
    }
}

/// True iff the (flat, degrade-to-oracle) health-mark price has
/// reached the bankruptcy price `bp` — i.e. the position's equity is ≤ 0. `bp` is by
/// construction the equity-zero price (long: below entry, short: above), so a long is
/// bankrupt at `mark ≤ bp` and a short at `mark ≥ bp`. `auto_deleverage` settles at
/// `bp` (a full-collateral wipe), so it may fire ONLY on a truly-bankrupt position;
/// a mark-solvent (equity > 0) one is handled by ordinary liquidation, which returns
/// the residual. Pure + host-tested so the invariant can't silently regress.
#[inline]
fn adl_bankruptcy_reached(side: u8, health_mark: u64, bp_ticks: u64) -> bool {
    if side == 0 {
        health_mark <= bp_ticks // long: price fell to/below bankruptcy
    } else {
        health_mark >= bp_ticks // short: price rose to/above bankruptcy
    }
}

fn settle_position_funding(
    market_cum_funding_index: i128,
    mark_price_ticks: u64,
    tick_size: u64,
    position: &mut state::PositionAccount,
    trader_state: &mut TraderStateAccount,
    residual_quote_lots: &mut u128,
) -> Result<i64> {
    if position.size_lots == 0 {
        position.set_cum_funding_index(market_cum_funding_index);
        return Ok(0);
    }
    // notional = size × mark_price × tick_size (quote lots); mark-priced to match
    // assess_margin's funding term (RISK-M2).
    let notional_u128 = (position.size_lots as u128)
        .checked_mul(mark_price_ticks as u128)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?
        .checked_mul(tick_size as u128)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    require!(
        notional_u128 <= u64::MAX as u128,
        CloberError::ArithmeticOverflow
    );
    let notional = notional_u128 as u64;

    let is_long = position.side == 0;
    let owed_i128 = funding_owed(
        is_long,
        notional,
        market_cum_funding_index,
        position.cum_funding_index(),
    )?;
    let owed_i64 = if owed_i128 > i64::MAX as i128 {
        i64::MAX
    } else if owed_i128 < i64::MIN as i128 {
        i64::MIN
    } else {
        owed_i128 as i64
    };

    // Isolated → per-position bucket; cross → pooled trader collateral. The
    // Kani-proven `route_funding` core moves the chosen bucket and the solvency
    // Residual equal-and-opposite (RISK-1 conservation), clamping a payment to
    // availability (the unpaid remainder is absorbed as the anchor advances).
    let is_isolated = position.collateral_quote_lots > 0;
    let bucket = if is_isolated {
        position.collateral_quote_lots
    } else {
        trader_state.collateral_quote_lots
    };
    let (new_bucket, new_residual) = route_funding(owed_i64, bucket, *residual_quote_lots)
        .map_err(|e| match e {
            FundingRouteErr::Overflow => error!(CloberError::ArithmeticOverflow),
        })?;
    if is_isolated {
        position.collateral_quote_lots = new_bucket;
    } else {
        trader_state.collateral_quote_lots = new_bucket;
    }
    *residual_quote_lots = new_residual;

    position.funding_paid_quote_lots = position
        .funding_paid_quote_lots
        .checked_add(owed_i64)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    position.set_cum_funding_index(market_cum_funding_index);
    Ok(owed_i64)
}

fn apply_fill_to_position(
    pos: &mut state::PositionAccount,
    fill_side: Side,
    fill_size_lots: u64,
    fill_price_ticks: u64,
    funding_index_now: i128,
    tick_size: u64,
) -> Result<()> {
    // Fund-critical arithmetic lives in the pure, Kani-proven `position_math`
    // core (open / stack-VWAP / reduce-flip + H-1 tick_size PnL scaling). This
    // handler is now just the account-plumbing shell: it maps the verified
    // outcome onto the `PositionAccount`, accumulates realized PnL, and applies
    // the funding-index reset at the points the core flags. The LP pool's
    // on-book maker inventory settles through the SAME core (pool-backed CLOB),
    // so a trader and the pool are provably priced by identical math.
    use matcher::position_math as pm;
    let outcome = pm::apply_fill(
        pm::Pos {
            side: pos.side,
            size_lots: pos.size_lots,
            entry_ticks: pos.entry_price_ticks,
        },
        fill_side as u8,
        fill_size_lots,
        fill_price_ticks,
        tick_size,
    )
    .map_err(|e| match e {
        pm::PosMathError::Overflow => error!(CloberError::ArithmeticOverflow),
        pm::PosMathError::Underflow => error!(CloberError::ArithmeticUnderflow),
        pm::PosMathError::DivByZero => error!(CloberError::DivisionByZero),
    })?;
    pos.side = outcome.pos.side;
    pos.size_lots = outcome.pos.size_lots;
    pos.entry_price_ticks = outcome.pos.entry_ticks;
    pos.realized_pnl_quote_lots = pos
        .realized_pnl_quote_lots
        .checked_add(outcome.realized_pnl_quote_lots)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    if outcome.reset_funding {
        pos.set_cum_funding_index(funding_index_now);
    }
    Ok(())
}

fn clamp_i128_to_i64(v: i128) -> i64 {
    if v > i64::MAX as i128 {
        i64::MAX
    } else if v < i64::MIN as i128 {
        i64::MIN
    } else {
        v as i64
    }
}

/// Materialise a realized-PnL delta into the trader's
/// collateral. Closes the gap documented in `docs/MARGIN_MATH.md §8.1`:
/// `apply_fill_to_position` accumulates realized PnL on
/// `pos.realized_pnl_quote_lots` (informational), and this helper
/// converts it into actual spendable collateral so a trader closing a
/// winning position can withdraw the profit and a trader closing a
/// losing position has their collateral debited.
///
/// Bucket routing matches the fee-routing rule in `apply_fill`:
///
///   isolated (position.collateral_quote_lots > 0)
///     → mutate position.collateral_quote_lots
///   cross
///     → mutate trader_state.collateral_quote_lots
///
/// Loss truncation:
///
///   * Isolated path: saturating_sub on the per-position bucket. If the
///     loss exceeds the isolated collateral the bucket goes to 0 and
///     the position becomes liquidatable on the next health check —
///     same conservative semantics as `settle_funding`.
///   * Cross path: checked_sub. A loss that exceeds
///     `trader_state.collateral_quote_lots` would put the trader's
///     pooled collateral negative, which is impossible; we return
///     `InsufficientCollateral` so the fill aborts. In practice the
///     pre-fill margin check should already have caught this — but
///     defense in depth: never let collateral go negative on the cross
///     path.
///
/// `delta` is signed: positive = trader gained (credit), negative =
/// trader lost (debit).
/// H6 (bad-debt socialization) — pure math for the cross-pool loss case.
/// Returns `(new_cross_collateral, shortfall)`: the pool is drawn down to cover
/// as much of the loss as it can, and any remainder (the position was bankrupt —
/// its loss exceeds its backing) is surfaced as `shortfall` for the caller to
/// cover from the insurance fund. Pure → host-testable.
#[inline]
fn cross_loss_shortfall(debit: u64, cross_collateral: u64) -> (u64, u64) {
    let covered = debit.min(cross_collateral);
    (cross_collateral - covered, debit - covered)
}

/// H6 / H7 — machine-checked solvency invariants for the realized-loss money
/// path, proved EXHAUSTIVELY over all u64 inputs by Kani (CBMC bounded model
/// checking). Together the bad-debt waterfall (H6) and the haircut-Residual
/// credit (H7) depend on these properties; they prove value can be neither
/// minted nor destroyed on a loss settlement. Runs in the CI Kani job
/// §3.2 P4: the RISK-1 funding-routing conservation invariant, machine-proved over
/// the whole symbolic input domain. `route_funding` (used by both `settle_funding`
/// and `apply_fill`) can NEVER mint or burn protocol collateral: whatever leaves
/// the collateral bucket lands in the solvency Residual, and vice-versa.
#[cfg(kani)]
mod funding_routing_proofs {
    use super::{route_funding, FundingRouteErr};

    /// Conservation: `Δcollateral == −Δresidual` for ALL (owed, collateral,
    /// residual) when the routing succeeds. Residual is ranged over `u64` (its
    /// realistic domain) so the proof targets value-conservation, not the
    /// trivially-unreachable u128 boundary.
    #[kani::proof]
    fn funding_routing_conserves_value() {
        let owed: i64 = kani::any();
        let collateral: u64 = kani::any();
        let residual: u128 = kani::any::<u64>() as u128;
        if let Ok((new_col, new_res)) = route_funding(owed, collateral, residual) {
            let d_col: i128 = new_col as i128 - collateral as i128;
            let d_res: i128 = new_res as i128 - residual as i128;
            assert!(d_col == -d_res);
        }
    }

    /// A payment never debits more than the bucket holds (no underflow), and a
    /// receipt never reduces the bucket — collateral moves one-signed per `owed`.
    #[kani::proof]
    fn funding_routing_bounded_and_one_signed() {
        let owed: i64 = kani::any();
        let collateral: u64 = kani::any();
        let residual: u128 = kani::any::<u64>() as u128;
        if let Ok((new_col, _)) = route_funding(owed, collateral, residual) {
            match owed.cmp(&0) {
                core::cmp::Ordering::Greater => assert!(new_col <= collateral), // pays ⇒ bucket ↓ (clamped)
                core::cmp::Ordering::Less => assert!(new_col >= collateral), // receives ⇒ bucket ↑
                core::cmp::Ordering::Equal => assert!(new_col == collateral), // no funding ⇒ unchanged
            }
        }
    }

    /// `FundingRouteErr` is only ever produced on a genuine checked-arith failure,
    /// never on the owed==0 no-op path.
    #[kani::proof]
    fn funding_routing_zero_is_noop() {
        let collateral: u64 = kani::any();
        let residual: u128 = kani::any::<u64>() as u128;
        let r = route_funding(0, collateral, residual);
        assert!(r == Ok((collateral, residual)));
        let _ = FundingRouteErr::Overflow; // reference the enum
    }

    /// A receipt is clamped to the Residual it is paid out of: it never draws the
    /// Residual below zero (no revert / no underflow) and never credits collateral
    /// by more than the Residual could back. This is the liveness property that
    /// keeps the funding leg from wedging the FIFO ring at an exhausted Residual.
    #[kani::proof]
    fn funding_receipt_clamped_to_residual() {
        let owed: i64 = kani::any();
        kani::assume(owed < 0);
        let collateral: u64 = kani::any();
        let residual: u128 = kani::any::<u64>() as u128;
        if let Ok((new_col, new_res)) = route_funding(owed, collateral, residual) {
            // Residual only ever shrinks and stays non-negative (u128, no wrap).
            assert!(new_res <= residual);
            // Collateral credited by exactly the drop in Residual, itself capped
            // at both the amount owed and the Residual available.
            let credited = (new_col - collateral) as u128;
            assert!(credited == residual - new_res);
            assert!(credited <= residual);
            assert!(credited <= owed.unsigned_abs() as u128);
        }
    }
}

/// (`cargo kani --package clober --features no-entrypoint`).
#[cfg(kani)]
mod h6_h7_solvency_proofs {
    use super::cross_loss_shortfall;

    /// The loss is split with EXACT conservation, and the collateral reported as
    /// removed — which H7 credits to the haircut Residual — NEVER exceeds the
    /// loss, so the Residual can never be over-credited and `h` can never be
    /// inflated (no value mint). The pool never underflows.
    #[kani::proof]
    fn cross_loss_shortfall_conserves_and_never_overcredits() {
        let debit: u64 = kani::any();
        let cross: u64 = kani::any();
        let (new_cross, shortfall) = cross_loss_shortfall(debit, cross);
        let removed = cross - new_cross; // collateral consumed (no underflow: new_cross ≤ cross)

        // (1) Pool conservation: nothing created/destroyed in the cross pool.
        assert!(new_cross + removed == cross);
        // (2) Loss split: covered (removed) + uncovered (shortfall) == the loss.
        assert!(removed + shortfall == debit);
        // (3) NO OVER-CREDIT (the H7 solvency invariant): Residual is credited by
        //     `removed`, which can NEVER exceed the loss → `h` is never inflated.
        assert!(removed <= debit);
        // (4) Pool never negative; drained to exactly 0 iff the loss covers it.
        assert!(new_cross <= cross);
        if debit >= cross {
            assert!(new_cross == 0);
        }
        // (5) No insurance draw (shortfall) when the pool fully covers the loss.
        if debit <= cross {
            assert!(shortfall == 0);
        }
    }

    /// A realized LOSS only ever DECREASES the debited bucket, never the other,
    /// and never debits MORE than the loss (no collateral destroyed beyond it).
    /// Cross losses are constrained to the covered case (the bankrupt case is
    /// intercepted upstream by `cross_loss_shortfall`); isolated losses saturate.
    #[kani::proof]
    fn realized_pnl_routing_loss_bounded_and_one_sided() {
        let mag: u64 = kani::any();
        let isolated: bool = kani::any();
        let iso: u64 = kani::any();
        let cross: u64 = kani::any();
        if !isolated {
            kani::assume(mag <= cross); // covered cross loss (no underflow / error)
        }
        let delta = -(mag as i128);
        let (new_iso, new_cross) =
            super::compute_realized_pnl_routing(delta, isolated, iso, cross).unwrap();
        if isolated {
            assert!(new_iso <= iso); // bucket only shrinks
            assert!(new_cross == cross); // cross pool untouched on the isolated path
            assert!(iso - new_iso <= mag); // never debits more than the loss
        } else {
            assert!(new_iso == iso); // isolated bucket untouched on the cross path
            assert!(new_cross <= cross);
            assert!(cross - new_cross == mag); // exact debit, no more, no less
        }
    }

    /// A realized GAIN credits EXACTLY the routed bucket by exactly the gain, and
    /// leaves the other bucket untouched (proved for the non-overflow case — the
    /// function returns Err on overflow rather than wrapping).
    #[kani::proof]
    fn realized_pnl_routing_gain_credits_exactly_one_bucket() {
        let mag: u64 = kani::any();
        let isolated: bool = kani::any();
        let iso: u64 = kani::any();
        let cross: u64 = kani::any();
        if isolated {
            kani::assume(iso.checked_add(mag).is_some());
        } else {
            kani::assume(cross.checked_add(mag).is_some());
        }
        let delta = mag as i128;
        let (new_iso, new_cross) =
            super::compute_realized_pnl_routing(delta, isolated, iso, cross).unwrap();
        if isolated {
            assert!(new_iso == iso + mag);
            assert!(new_cross == cross);
        } else {
            assert!(new_cross == cross + mag);
            assert!(new_iso == iso);
        }
    }
}

/// R-2 emergency recovery core (pure, Kani-proven in `force_close_proofs`).
/// Settles a TRAPPED position's realized PnL (valued at the oracle price) against
/// the insurance fund as the counterparty of last resort, so a trader whose ER
/// sequencer is dead/byzantine can close on L1 and free the collateral that
/// `open_positions > 0` otherwise locks. Returns `(new_bucket, new_insurance)`.
///
/// CONSERVATION (V = C_tot + I + Residual): the trader's bucket and the insurance
/// fund move EXACTLY equal-and-opposite — `Δbucket == −Δinsurance` — so no value
/// is minted or burned; the Residual is untouched. BOTH directions clamp so
/// neither balance can under/overflow: a gain the fund cannot back is haircut
/// (the trader is shorted — an acceptable last-resort outcome), and a loss beyond
/// the trader's bucket is absorbed (the fund receives only what the trader held).
/// The `u64::MAX` headroom clamps are unreachable at real balances; they keep the
/// core total so the conservation proof holds over the whole input domain.
fn force_close_against_insurance(pnl: i128, bucket: u64, insurance: u64) -> (u64, u64) {
    if pnl > 0 {
        let gain = if pnl > u64::MAX as i128 {
            u64::MAX
        } else {
            pnl as u64
        };
        // Paid out of the fund, capped at what it holds AND the bucket's headroom.
        let paid = gain.min(insurance).min(u64::MAX - bucket);
        (bucket + paid, insurance - paid) // paid ≤ insurance ⇒ no underflow
    } else if pnl < 0 {
        let loss = if pnl < -(u64::MAX as i128) {
            u64::MAX
        } else {
            (-pnl) as u64
        };
        // Paid to the fund, capped at the trader's bucket AND the fund's headroom.
        let paid = loss.min(bucket).min(u64::MAX - insurance);
        (bucket - paid, insurance + paid) // paid ≤ bucket ⇒ no underflow
    } else {
        (bucket, insurance)
    }
}

#[cfg(test)]
mod force_close_core_tests {
    use super::force_close_against_insurance;

    #[test]
    fn gain_within_fund_credits_trader_debits_fund() {
        assert_eq!(
            force_close_against_insurance(1_000, 500, 4_000),
            (1_500, 3_000)
        );
    }

    #[test]
    fn gain_beyond_fund_is_haircut() {
        // Fund only holds 300 of the 1000 owed: trader gets 300, fund drains to 0.
        assert_eq!(force_close_against_insurance(1_000, 500, 300), (800, 0));
    }

    #[test]
    fn loss_within_bucket_debits_trader_credits_fund() {
        assert_eq!(
            force_close_against_insurance(-1_000, 5_000, 200),
            (4_000, 1_200)
        );
    }

    #[test]
    fn loss_beyond_bucket_is_absorbed() {
        // Trader can only pay 500 of the 1000 loss; fund gains only 500.
        assert_eq!(force_close_against_insurance(-1_000, 500, 200), (0, 700));
    }

    #[test]
    fn conserves_value_each_direction() {
        for &(pnl, b, i) in &[
            (1_000i128, 500u64, 4_000u64),
            (1_000, 500, 300),
            (-1_000, 5_000, 200),
            (-1_000, 500, 200),
            (0, 123, 456),
        ] {
            let (nb, ni) = force_close_against_insurance(pnl, b, i);
            assert_eq!(nb as i128 - b as i128, -(ni as i128 - i as i128));
        }
    }
}

#[cfg(kani)]
mod force_close_proofs {
    use super::force_close_against_insurance;

    /// CONSERVATION: the trader bucket and the insurance fund always move
    /// equal-and-opposite, over the WHOLE (pnl, bucket, insurance) domain — so an
    /// emergency oracle force-close can never mint or burn protocol value.
    #[kani::proof]
    fn force_close_conserves_value() {
        let pnl: i128 = kani::any();
        let bucket: u64 = kani::any::<u64>();
        let insurance: u64 = kani::any::<u64>();
        let (nb, ni) = force_close_against_insurance(pnl, bucket, insurance);
        assert!(nb as i128 - bucket as i128 == -(ni as i128 - insurance as i128));
    }

    /// A gain never drains the fund below zero and a loss never drives the trader
    /// bucket below zero (no underflow / no panic on any input).
    #[kani::proof]
    fn force_close_never_underflows() {
        let pnl: i128 = kani::any();
        let bucket: u64 = kani::any::<u64>();
        let insurance: u64 = kani::any::<u64>();
        let (nb, ni) = force_close_against_insurance(pnl, bucket, insurance);
        if pnl > 0 {
            assert!(ni <= insurance && nb >= bucket); // fund pays, trader credited
        } else if pnl < 0 {
            assert!(nb <= bucket && ni >= insurance); // trader pays, fund credited
        } else {
            assert!(nb == bucket && ni == insurance);
        }
    }
}

/// H6 — cover a realized-loss shortfall (bad debt) from the insurance fund,
/// saturating at the fund balance. This is PURE ACCOUNTING — no token transfer:
/// the shared `quote_vault` already physically holds the funds; the counterparty
/// was already credited their gain, and this reconciles the internal ledger so
/// the deficit is absorbed by the fund rather than reverting settlement (which
/// would strand a bankrupt position AND diverge the book from settlement, since
/// the maker order was already consumed in `place_taker_order`). Any
/// remainder the fund cannot cover is surfaced via the event (awaiting ADL).
fn cover_bad_debt<'info>(
    insurance_fund: &mut Box<Account<'info, InsuranceFundAccount>>,
    market: Pubkey,
    trader: Pubkey,
    shortfall: u64,
    market_is_permissionless: bool,
) {
    if shortfall == 0 {
        return;
    }
    // HIP-3 isolation: a PERMISSIONLESS market's bad debt is NEVER socialized to
    // the shared insurance fund — a hostile creator must not be able to drain the
    // global backstop. The shortfall is left uncovered (borne by that market's
    // own participants via ADL + the per-domain paper-profit haircut); the event
    // still reports it in full for the keeper/ADL path.
    let covered = if market_is_permissionless {
        0
    } else {
        shortfall.min(insurance_fund.balance_quote_lots)
    };
    insurance_fund.balance_quote_lots -= covered;
    insurance_fund.total_payouts = insurance_fund.total_payouts.saturating_add(covered);
    emit!(BadDebtSocializedEvent {
        market,
        trader,
        shortfall_quote_lots: shortfall,
        covered_by_insurance_quote_lots: covered,
        uncovered_quote_lots: shortfall - covered,
    });
}

/// H7 — accrue an opted-in position's realized LOSS to the market haircut
/// Residual. When a position closes at a loss its collateral is removed (C_tot
/// ↓), so the solvency residual `V − C_tot − I` rises by the SAME amount — the
/// lost collateral becomes backing for others' released gains. Without this the
/// Residual only ever FELL (opted gains park in the reserve and later debit
/// Residual at `convert_position`), so it ratcheted toward 0 and `h → 0` for
/// every trader, breaking the conservation identity. Scoped to OPTED positions
/// (`position_haircut` present): non-opted positions never participate in the
/// Residual on either leg. `collateral_removed` is ALWAYS ≤ |loss| (the amount
/// actually debited, not the full delta on a saturated/bankrupt close), so the
/// Residual can never be OVER-credited — `h` cannot be inflated (no mint).
fn accrue_haircut_loss<'info>(
    market_haircut: Option<&mut Box<Account<'info, extended_state::MarketHaircutStateAccount>>>,
    position_opted: bool,
    collateral_removed: u64,
) -> Result<()> {
    if collateral_removed == 0 || !position_opted {
        return Ok(());
    }
    if let Some(mh) = market_haircut {
        mh.residual_quote_lots = mh
            .residual_quote_lots
            .checked_add(collateral_removed as u128)
            .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
        mh.realized_loss_total_quote_lots = mh
            .realized_loss_total_quote_lots
            .checked_add(collateral_removed as u128)
            .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    }
    Ok(())
}

/// Returns `(shortfall, collateral_removed)`:
/// - `shortfall` — uncovered cross-pool deficit (0 except a bankrupt cross
///   close); the caller covers it via `cover_bad_debt`.
/// - `collateral_removed` — collateral actually DEBITED by a loss (0 for gains
///   / no-op). The caller accrues this to the haircut Residual for opted
///   positions so the `V−C_tot−I` identity stays conserved. It is ALWAYS
///   ≤ |loss| (the removed amount, never the full delta on a bankrupt/saturated
///   close), so Residual can never be OVER-credited — `h` cannot be inflated.
///
/// Gains, isolated losses, and fully-covered cross losses are unaffected
/// by this routing.
fn apply_realized_pnl_direct<'info>(
    delta: i128,
    isolated: bool,
    position: &mut AccountLoader<'info, state::PositionAccount>,
    trader_state: &mut AccountLoader<'info, TraderStateAccount>,
) -> Result<(u64, u64)> {
    let cross_collateral = trader_state.load()?.collateral_quote_lots;
    let iso_collateral = position.load()?.collateral_quote_lots;
    // H6: a cross-pool loss that EXCEEDS the pool is a bankrupt position. Rather
    // than reverting (the old `checked_sub` → InsufficientCollateral inside
    // compute_realized_pnl_routing), saturate the pool to 0 and surface the
    // shortfall so the caller draws it from insurance. Isolated losses keep
    // their existing saturate-to-0 semantics (bucket-only risk by design).
    if delta < 0 && !isolated {
        let debit = if delta < -(u64::MAX as i128) {
            u64::MAX
        } else {
            (-delta) as u64
        };
        if debit > cross_collateral {
            let (new_cross, shortfall) = cross_loss_shortfall(debit, cross_collateral);
            trader_state.load_mut()?.collateral_quote_lots = new_cross; // == 0
                                                                        // removed = the whole pool; the uncovered remainder is `shortfall`.
            return Ok((shortfall, cross_collateral));
        }
    }
    // ── Socialize ISOLATED bankruptcy too ──
    // Saturating an exhausted isolated bucket to 0 without surfacing a
    // shortfall would be a silent vault deficit: the counterparty's gain is
    // credited in full from the shared vault while the uncovered remainder
    // vanishes from the books. Mirror the cross-loss waterfall: surface the
    // remainder so the caller draws it from insurance (`cover_bad_debt`, clamped to
    // the fund balance — never negative, never an unbacked mint), RECORDING the bad
    // debt instead of hiding it. This is the standard isolated-margin posture and is
    // strictly safer than the prior silent drain. Same pure `cross_loss_shortfall`
    // (it operates on any bucket). Only the genuine-bankruptcy case changes; a
    // within-bucket isolated loss still falls through unchanged.
    if delta < 0 && isolated {
        let debit = if delta < -(u64::MAX as i128) {
            u64::MAX
        } else {
            (-delta) as u64
        };
        if debit > iso_collateral {
            let (new_iso, shortfall) = cross_loss_shortfall(debit, iso_collateral);
            position.load_mut()?.collateral_quote_lots = new_iso; // == 0
            return Ok((shortfall, iso_collateral));
        }
    }
    let (new_iso, new_cross) =
        compute_realized_pnl_routing(delta, isolated, iso_collateral, cross_collateral)?;
    position.load_mut()?.collateral_quote_lots = new_iso;
    trader_state.load_mut()?.collateral_quote_lots = new_cross;
    // collateral_removed: the debited bucket's decrease (loss only; gains = 0).
    let removed = if delta < 0 {
        if isolated {
            iso_collateral.saturating_sub(new_iso)
        } else {
            cross_collateral.saturating_sub(new_cross)
        }
    } else {
        0
    };
    Ok((0, removed))
}

/// Apply_realized_pnl_delta with optional H-haircut routing.
///
/// When `position_haircut` is `Some(...)`:
///   - positive delta (gain) is pushed into the reserve via
///     `matcher::haircut::apply_release`. **No collateral mutation.**
///     The credit lands in collateral only after the warmup completes
///     and `convert_position` is called.
///   - negative delta (loss) bypasses the haircut entirely and debits
///     collateral directly — losses are senior to capital.
///
/// When `position_haircut` is `None`: identical to
/// `apply_realized_pnl_direct` v1 (the legacy direct credit/debit path).
///
/// This is the **opt-in** wire-in: markets without a HaircutState
/// keep their existing behaviour bit-for-bit. Markets with HaircutState
/// (+ a per-position HaircutState provided in remaining accounts) gain
/// the junior-claim protection automatically on every fill.
fn apply_realized_pnl_delta<'info>(
    delta: i128,
    isolated: bool,
    position: &mut AccountLoader<'info, state::PositionAccount>,
    trader_state: &mut AccountLoader<'info, TraderStateAccount>,
    position_haircut: Option<&mut Box<Account<'info, extended_state::PositionHaircutStateAccount>>>,
    now_slot: u64,
    // Market warmup FLOOR (h_min). apply_release restarts
    // the warmup when a release lands on a reserve whose old_elapsed >= h_min (i.e.
    // maturation has begun), stopping a fresh gain from inheriting matured status.
    // 0 when the haircut engine is disabled (position_haircut is then None, unused).
    h_min_slots: u64,
) -> Result<(u64, u64)> {
    if delta > 0 {
        if let Some(ph) = position_haircut {
            // Haircut path: route to reserve, no collateral mutation.
            let gain_u64: u64 = if delta > u64::MAX as i128 {
                u64::MAX
            } else {
                delta as u64
            };
            let pre = matcher::haircut::PositionHaircutSnapshot {
                released_reserve_quote_lots: ph.released_reserve_quote_lots,
                released_attached_at_slot: ph.released_attached_at_slot,
                matured_pos_quote_lots: ph.matured_pos_quote_lots,
                original_reserve_at_attach: ph.original_reserve_at_attach,
            };
            let post = matcher::haircut::apply_release(pre, gain_u64, now_slot, h_min_slots)
                .map_err(map_haircut_error)?;
            ph.released_reserve_quote_lots = post.released_reserve_quote_lots;
            ph.released_attached_at_slot = post.released_attached_at_slot;
            ph.matured_pos_quote_lots = post.matured_pos_quote_lots;
            ph.original_reserve_at_attach = post.original_reserve_at_attach;
            // Gains routed to the haircut reserve never touch collateral → no
            // shortfall and no collateral removed.
            return Ok((0, 0));
        }
    }
    // Loss path AND legacy non-haircut gain path both fall through to v1, which
    // returns (uncovered cross-loss shortfall [H6], collateral removed [H7]).
    apply_realized_pnl_direct(delta, isolated, position, trader_state)
}

/// Pure math for the realized-PnL routing. Returns
/// `(new_position_collateral, new_trader_state_collateral)`. Separated
/// from `apply_realized_pnl_direct` so the routing rules are unit
/// testable without Anchor-account scaffolding.
///
/// Rules (matching `apply_realized_pnl_direct`'s contract):
///
/// * `delta > 0` (gain) — credit the isolated bucket if isolated,
///   else the cross pool. `checked_add` overflows → ArithmeticOverflow.
/// * `delta < 0` (loss) — debit the isolated bucket if isolated, else
///   the cross pool. Isolated bucket saturates to 0 (loss-truncation,
///   same semantics as `settle_funding`). Cross pool uses
///   `checked_sub` and surfaces `InsufficientCollateral` rather than
///   going negative.
/// * `delta == 0` — no-op.
fn compute_realized_pnl_routing(
    delta: i128,
    isolated: bool,
    iso_collateral: u64,
    cross_collateral: u64,
) -> Result<(u64, u64)> {
    if delta > 0 {
        let credit_u64 = if delta > u64::MAX as i128 {
            u64::MAX
        } else {
            delta as u64
        };
        if isolated {
            let new_iso = iso_collateral
                .checked_add(credit_u64)
                .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
            Ok((new_iso, cross_collateral))
        } else {
            let new_cross = cross_collateral
                .checked_add(credit_u64)
                .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
            Ok((iso_collateral, new_cross))
        }
    } else if delta < 0 {
        let debit_u64 = if delta < -(u64::MAX as i128) {
            u64::MAX
        } else {
            (-delta) as u64
        };
        if isolated {
            // Loss-truncation: saturate to 0; remainder surfaces via
            // the next health check.
            Ok((iso_collateral.saturating_sub(debit_u64), cross_collateral))
        } else {
            let new_cross = cross_collateral
                .checked_sub(debit_u64)
                .ok_or_else(|| error!(CloberError::InsufficientCollateral))?;
            Ok((iso_collateral, new_cross))
        }
    } else {
        Ok((iso_collateral, cross_collateral))
    }
}

/// Verify that an account presented as a TraderState was
/// derived from the expected `(wallet, sub_index)` seed pair. Returns
/// `WrongTrader` if the derivation doesn't match the account's actual
/// pubkey.
///
/// This closes the 1-byte routing-attack surface opened by the
/// seeds relaxation on `ApplyFill`. The handler relaxation lets the
/// sequencer pass any TraderState whose `.trader` field matches the
/// order's `.trader`; without this re-derivation check, a hostile
/// sequencer could pass `[STATE_SEED, trader, &[2]]` for an order
/// placed by sub_index=1.
///
/// Seed convention (matches `open_trader_state` and
/// `open_trader_sub_account`):
///
///   sub_index == 0 → `[TraderStateAccount::SEED, trader.as_ref()]`        (main)
///   sub_index >  0 → `[TraderStateAccount::SEED, trader.as_ref(), &[sub_index]]` (sub)
///
/// CU: uses the account's stored canonical `bump` + `create_program_address`
/// (one hash) instead of `find_program_address` (a descending bump search,
/// ~1.5k CU). Same security: `open_trader_state` / `open_trader_sub_account`
/// store the canonical bump at init via Anchor's `init`+`bump`, and a
/// non-canonical-bump TraderState cannot be program-initialized — so the
/// stored bump IS the canonical one. This mirrors `verify_position_pda`.
/// init_if_needed zero-copy helper: Anchor's `AccountLoader` writes the 8-byte
/// discriminator only in `exit()` (end of instruction), so a freshly-created
/// account has a zeroed discriminator *during* the handler and any
/// `load()`/`load_mut()` fails `AccountDiscriminatorMismatch`. This stamps the
/// discriminator immediately if absent; it is a no-op for an account that is
/// already initialized.
fn stamp_zc_discriminator(ai: &AccountInfo<'_>, disc: &[u8]) -> Result<()> {
    // Bounds-check before slicing: every current caller passes an Anchor-`init`'d
    // account sized to its struct (>= 8 bytes), but an unchecked `[..8]` /
    // `[..disc.len()]` would panic on a short account, so gate it so a future
    // caller (or a truncated account) fails closed instead of bricking the ix.
    let data_len = ai.try_borrow_data()?.len();
    require!(
        data_len >= disc.len() && disc.len() >= 8,
        CloberError::OutOfRange
    );
    let is_fresh = ai.try_borrow_data()?[..8].iter().all(|&b| b == 0);
    if is_fresh {
        ai.try_borrow_mut_data()?[..disc.len()].copy_from_slice(disc);
    }
    Ok(())
}

/// Locate the per-market FillCommitmentAccount in
/// `remaining_accounts`, if armed. Truly optional — returns `None` when no
/// matching account is passed (legacy behaviour). An account qualifies iff it is
/// owned by THIS program (so only `init_fill_commitment` at the canonical PDA
/// could have created it) AND its disc + market binding + length check out
/// (`buffer_check`). That pair uniquely identifies the real account without a
/// `find_program_address` on the hot path.
fn find_fill_commitment<'a, 'info>(
    remaining: &'a [AccountInfo<'info>],
    program_id: &Pubkey,
    market_bytes: &[u8; 32],
) -> Option<&'a AccountInfo<'info>> {
    for ai in remaining {
        if ai.owner == program_id {
            if let Ok(data) = ai.try_borrow_data() {
                if matcher::fill_commitment::buffer_check(&data, market_bytes).is_ok() {
                    return Some(ai);
                }
            }
        }
    }
    None
}

/// Locate this market's `FillOutboxAccount` in `remaining_accounts` (mirrors
/// `find_fill_commitment`). Program-owned, disc-checked, market-bound — the outbox
/// disc (`FBoutbx\0`) is distinct from the ring disc, so this never returns the
/// ring account (and vice-versa), guaranteeing the two borrows in
/// `place_taker_order` are on different accounts.
fn find_fill_outbox<'a, 'info>(
    remaining: &'a [AccountInfo<'info>],
    program_id: &Pubkey,
    market_bytes: &[u8; 32],
) -> Option<&'a AccountInfo<'info>> {
    for ai in remaining {
        if ai.owner == program_id {
            if let Ok(data) = ai.try_borrow_data() {
                if matcher::fill_outbox::outbox_check(&data, market_bytes).is_ok() {
                    return Some(ai);
                }
            }
        }
    }
    None
}

/// 2.3: PDA-scan `remaining_accounts` for a `recipient`'s canonical
/// `FeeAccrualAccount`. Mirrors `find_fill_commitment` — matches by
/// program-ownership + writability + the Anchor discriminator + the embedded
/// `recipient` bytes, NOT by position, so accrual accounts are purely additive
/// to the fill's account list (absent ⇒ the caller falls back to emit-only).
/// The discriminator disambiguates from the (hand-rolled, discriminator-less)
/// fill-commitment ring / outbox that also live in `remaining_accounts`.
fn find_fee_accrual<'a, 'info>(
    remaining: &'a [AccountInfo<'info>],
    program_id: &Pubkey,
    recipient: &Pubkey,
) -> Option<&'a AccountInfo<'info>> {
    let disc = <state::FeeAccrualAccount as anchor_lang::Discriminator>::DISCRIMINATOR;
    let want = recipient.to_bytes();
    for ai in remaining {
        if ai.owner != program_id || !ai.is_writable {
            continue;
        }
        if let Ok(data) = ai.try_borrow_data() {
            if data.len() >= state::FeeAccrualAccount::ACCRUED_OFFSET + 8
                && &data[..8] == disc
                && data[8..40] == want
            {
                return Some(ai);
            }
        }
    }
    None
}

/// 2.3: add `add` quote lots to a `FeeAccrualAccount`'s `accrued_quote_lots`,
/// writing the u64 in place at its fixed byte offset (checked-add, fail-closed on
/// overflow). Byte-level write mirrors the hot-path ring/permission handling and
/// avoids re-serializing an account that isn't a declared context account.
fn accrue_to_fee_account(ai: &AccountInfo<'_>, add: u64) -> Result<()> {
    let off = state::FeeAccrualAccount::ACCRUED_OFFSET;
    let mut data = ai.try_borrow_mut_data()?;
    require!(data.len() >= off + 8, CloberError::OutOfRange);
    let bytes: [u8; 8] = data[off..off + 8]
        .try_into()
        .map_err(|_| error!(CloberError::OutOfRange))?;
    let cur = u64::from_le_bytes(bytes);
    let new = cur
        .checked_add(add)
        .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
    data[off..off + 8].copy_from_slice(&new.to_le_bytes());
    Ok(())
}

/// Shared market-params validation — the immutability
/// of the measurement primitives + the mutable-field bounds. K-3: this is the SOLE
/// economic-param validator, used by the timelocked `propose_param_update` /
/// `execute_param_update`. The immediate `update_market_params` no longer changes
/// economic params (it only enables a disabled staleness gate and requires every
/// other field byte-identical via `hash_params`), so there are no inline checks
/// left to keep in sync. A proptest/BanksClient test pins a representative
/// rejection on the timelocked path.
/// Keccak of the borsh-serialized params — the
/// commitment stored at propose and re-checked at execute so the applied change is
/// exactly the pre-announced one. (borsh 1.x dropped the inherent `try_to_vec`;
/// serialize via `AnchorSerialize` into a buffer, as elsewhere in the crate.)
fn hash_params(p: &MarketParams) -> Result<[u8; 32]> {
    use anchor_lang::AnchorSerialize;
    let mut bytes = Vec::new();
    AnchorSerialize::serialize(p, &mut bytes).map_err(|_| error!(CloberError::OutOfRange))?;
    Ok(solana_keccak_hasher::hashv(&[&bytes]).0)
}

/// HIP-3: the hard safety envelope every PERMISSIONLESS market's params must
/// satisfy. Because any signer may call `create_permissionless_market`, the
/// params are attacker-controlled; this clamps them so the resulting market is
/// provably conservative no matter who created it — bounded leverage, a real
/// maintenance-margin floor, `IM ≥ MM` (the anti-self-liquidation invariant),
/// non-predatory fees, a fresh-oracle requirement, and bounded liquidation
/// incentives + fee shares. `hip3_params_are_safe` (Kani) proves that anything
/// this accepts satisfies the envelope. Authority-created markets bypass this
/// (they are already trusted); only the permissionless path calls it.
/// The numeric leverage/margin core of the HIP-3 safety envelope, as a pure
/// predicate so `hip3_params_are_safe` (Kani) proves exactly the deployed logic:
/// bounded leverage, a maintenance floor, `IM ≥ MM`, and `IM · leverage ≥
/// BPS_DENOM` (the advertised leverage is actually funded by the initial margin,
/// so the true max leverage `BPS/IM ≤ max_leverage ≤ HIP3_MAX_LEVERAGE`). The
/// `u32 → u64` widen makes the product overflow-free.
#[inline]
fn hip3_core_bounds_ok(max_leverage: u32, mm_bps: u32, im_bps: u32) -> bool {
    use constants::*;
    (1..=HIP3_MAX_LEVERAGE).contains(&max_leverage)
        && mm_bps >= HIP3_MIN_MAINTENANCE_MARGIN_BPS
        && im_bps >= mm_bps
        && (im_bps as u64) * (max_leverage as u64) >= BPS_DENOM as u64
}

fn validate_hip3_params(p: &MarketParams) -> Result<()> {
    use constants::*;
    // Measurement primitives must be real.
    require!(p.tick_size > 0, CloberError::OutOfRange);
    require!(p.base_lot_size > 0, CloberError::OutOfRange);
    require!(p.quote_lot_size > 0, CloberError::OutOfRange);
    require!(p.min_base_lots > 0, CloberError::OutOfRange);
    // Leverage capped; maintenance floored; IM ≥ MM (feeds the proven
    // withdraw-cannot-self-liquidate guarantee); IM consistent with the
    // advertised leverage. The numeric core is a shared predicate so the Kani
    // proof (`hip3_params_are_safe`) covers exactly the deployed logic.
    require!(
        hip3_core_bounds_ok(
            p.max_leverage,
            p.maintenance_margin_ratio_bps,
            p.initial_margin_ratio_bps,
        ),
        CloberError::OutOfRange
    );
    // Non-predatory economics.
    require!(
        p.taker_fee_bps <= HIP3_MAX_TAKER_FEE_BPS,
        CloberError::OutOfRange
    );
    require!(
        p.liq_penalty_bps <= HIP3_MAX_LIQ_BPS,
        CloberError::OutOfRange
    );
    require!(
        p.liquidator_reward_bps <= HIP3_MAX_LIQ_BPS,
        CloberError::OutOfRange
    );
    require!(
        p.referrer_share_bps <= HIP3_MAX_SHARE_BPS
            && p.builder_share_bps <= HIP3_MAX_SHARE_BPS
            && p.creator_share_bps <= HIP3_MAX_SHARE_BPS,
        CloberError::OutOfRange
    );
    // Fresh oracle required (bounded staleness), band configured.
    require!(
        p.oracle_staleness_max_seconds >= 1
            && p.oracle_staleness_max_seconds <= HIP3_MAX_ORACLE_STALENESS_SECS,
        CloberError::OutOfRange
    );
    require!(p.oracle_band_bps > 0, CloberError::OutOfRange);
    // Per-trader position must be bounded (no unbounded single-account OI).
    require!(
        p.max_position_lots_per_trader > 0,
        CloberError::OutOfRange
    );
    Ok(())
}

fn validate_market_params(current: &MarketParams, new: &MarketParams) -> Result<()> {
    // Immutability of the measurement primitives.
    require!(
        new.tick_size == current.tick_size,
        CloberError::OutOfRange
    );
    require!(
        new.base_lot_size == current.base_lot_size,
        CloberError::OutOfRange
    );
    require!(
        new.quote_lot_size == current.quote_lot_size,
        CloberError::OutOfRange
    );
    require!(
        new.min_base_lots == current.min_base_lots,
        CloberError::OutOfRange
    );
    // Mutable-field bounds.
    require!(new.max_leverage >= 1, CloberError::OutOfRange);
    require!(
        new.oracle_staleness_max_seconds > 0,
        CloberError::OutOfRange
    );
    require!(
        new.maintenance_margin_ratio_bps <= new.initial_margin_ratio_bps,
        CloberError::OutOfRange
    );
    require!(
        new.lp_max_growth_per_batch_bps <= constants::BPS_DENOM,
        CloberError::OutOfRange
    );
    require!(
        new.oracle_band_bps <= constants::MAX_ORACLE_BAND_BPS,
        CloberError::OutOfRange
    );
    require!(
        new.maintenance_margin_ratio_bps < 5_000,
        CloberError::OutOfRange
    );
    require!(
        new.initial_margin_ratio_bps < 5_000,
        CloberError::OutOfRange
    );
    require!(
        new.maintenance_margin_ratio_bps
            .saturating_add(new.concentration_extra_mmr_bps)
            < 5_000,
        CloberError::OutOfRange
    );
    require!(
        new.taker_fee_bps <= constants::MAX_FEE_TIER_BPS,
        CloberError::OutOfRange
    );
    require!(
        new.maker_rebate_bps.unsigned_abs() <= constants::MAX_FEE_TIER_BPS,
        CloberError::OutOfRange
    );
    require!(
        new.toxicity_tax_max_bps <= constants::MAX_FEE_TIER_BPS,
        CloberError::OutOfRange
    );
    require!(
        new.jit_bonus_rebate_bps <= constants::MAX_FEE_TIER_BPS,
        CloberError::OutOfRange
    );
    require!(new.liq_penalty_bps <= 5_000, CloberError::OutOfRange);
    require!(
        new.liquidator_reward_bps <= new.liq_penalty_bps,
        CloberError::OutOfRange
    );
    require!(
        new.funding_rate_max_bps_per_sec <= constants::BPS_DENOM,
        CloberError::OutOfRange
    );
    require!(
        new.funding_per_period_max_bps <= 5_000,
        CloberError::OutOfRange
    );
    require!(
        new.referrer_share_bps <= constants::BPS_DENOM
            && new.builder_share_bps <= constants::BPS_DENOM
            && new.creator_share_bps <= constants::BPS_DENOM,
        CloberError::OutOfRange
    );
    Ok(())
}

fn verify_trader_state_pda(
    sub_index: u8,
    trader: Pubkey,
    actual: Pubkey,
    bump: u8,
    program_id: &Pubkey,
) -> Result<()> {
    let expected = if sub_index == 0 {
        Pubkey::create_program_address(
            &[TraderStateAccount::SEED, trader.as_ref(), &[bump]],
            program_id,
        )
    } else {
        Pubkey::create_program_address(
            &[
                TraderStateAccount::SEED,
                trader.as_ref(),
                &[sub_index],
                &[bump],
            ],
            program_id,
        )
    }
    .map_err(|_| error!(CloberError::WrongTrader))?;
    require_keys_eq!(expected, actual, CloberError::WrongTrader);
    Ok(())
}

/// C-2 — re-derive a Position PDA from `(market, trader_state)` and assert
/// it matches `actual`. This binds a `remaining_accounts` position to THIS
/// trader_state, so a margin walk cannot be fed a different sub-account's
/// position, a stale/closed position, or any other program-owned account
/// with a chosen `mark_price`/size to understate risk. Uses the position's
/// stored bump + `create_program_address` (cheap — no bump search).
fn verify_position_pda(
    market_key: &Pubkey,
    trader_state_key: &Pubkey,
    bump: u8,
    actual: &Pubkey,
    program_id: &Pubkey,
) -> Result<()> {
    let expected = Pubkey::create_program_address(
        &[
            state::PositionAccount::SEED,
            market_key.as_ref(),
            trader_state_key.as_ref(),
            &[bump],
        ],
        program_id,
    )
    .map_err(|_| error!(CloberError::OutOfRange))?;
    require_keys_eq!(expected, *actual, CloberError::WrongTrader);
    Ok(())
}

/// Derive the canonical PositionAccount PDA for a
/// resting maker's `(trader, sub_index)` on `market`, so the matcher can match a
/// crossed REDUCE-ONLY maker order to its position (supplied read-only via
/// `remaining_accounts`) and cap the fill to the reducible size. Two derivations
/// (trader_state → position); invoked ONLY for reduce-only makers (rare on a normal
/// book), so the `find_program_address` cost is confined to that subset.
fn derive_maker_position_key(
    market_key: &Pubkey,
    trader: &Pubkey,
    sub_index: u8,
    program_id: &Pubkey,
) -> Pubkey {
    let trader_state = if sub_index == 0 {
        Pubkey::find_program_address(&[TraderStateAccount::SEED, trader.as_ref()], program_id).0
    } else {
        Pubkey::find_program_address(
            &[TraderStateAccount::SEED, trader.as_ref(), &[sub_index]],
            program_id,
        )
        .0
    };
    Pubkey::find_program_address(
        &[
            state::PositionAccount::SEED,
            market_key.as_ref(),
            trader_state.as_ref(),
        ],
        program_id,
    )
    .0
}

/// Unrealized PnL of one LP inventory position, in quote-lots, valued at a
/// price. `side` 0 = long (gain when price > entry), 1 = short (gain when price
/// < entry). Pure so the sign/scale is unit-testable independent of the handler.
fn lp_slot_unrealized_pnl(
    side: u8,
    size_lots: u64,
    entry_ticks: u64,
    price_ticks: u64,
    tick_size: u64,
) -> i128 {
    let diff = (price_ticks as i128) - (entry_ticks as i128);
    let sign: i128 = if side == 0 { 1 } else { -1 };
    (size_lots as i128)
        .saturating_mul(diff)
        .saturating_mul(tick_size as i128)
        .saturating_mul(sign)
}

/// Mark a v3 per-market LP pool's open inventory to the market's fresh L1
/// oracle, returning the signed unrealized PnL in quote lots (0 when flat).
/// Fails closed (`OracleTooStale`) when the pool holds inventory but the oracle
/// is missing/stale, so deposit and withdraw can never price shares off a
/// degraded mark. Uses the L1 oracle, not the ER mark, so it is
/// ER-stall-independent — identical to the singleton pool's marking.
fn lp_v3_inventory_mtm(
    side: u8,
    size_lots: u64,
    entry_ticks: u64,
    market: &MarketAccount,
    now_unix: i64,
) -> Result<i128> {
    if side == 255 || size_lots == 0 {
        return Ok(0);
    }
    let now = now_unix.max(0) as u64;
    let oracle = market.oracle_price_ticks;
    let max_age = market.params.oracle_staleness_max_seconds as u64;
    let published = market.oracle_published_at_unix_seconds;
    require!(
        oracle > 0 && published > 0 && now.saturating_sub(published) <= max_age,
        CloberError::OracleTooStale
    );
    Ok(lp_slot_unrealized_pnl(
        side,
        size_lots,
        entry_ticks,
        oracle,
        market.params.tick_size,
    ))
}

#[cfg(test)]
mod lp_mtm_tests {
    use super::lp_slot_unrealized_pnl;

    #[test]
    fn long_gain_and_loss() {
        // long 100 @ entry 100, tick 1: +10 ticks ⇒ +1000, -10 ticks ⇒ -1000.
        assert_eq!(lp_slot_unrealized_pnl(0, 100, 100, 110, 1), 1000);
        assert_eq!(lp_slot_unrealized_pnl(0, 100, 100, 90, 1), -1000);
    }

    #[test]
    fn short_gain_and_loss() {
        // short 100 @ entry 100: price DOWN is a gain, UP is a loss.
        assert_eq!(lp_slot_unrealized_pnl(1, 100, 100, 90, 1), 1000);
        assert_eq!(lp_slot_unrealized_pnl(1, 100, 100, 110, 1), -1000);
    }

    #[test]
    fn flat_at_entry_is_zero() {
        assert_eq!(lp_slot_unrealized_pnl(0, 100, 100, 100, 1), 0);
        assert_eq!(lp_slot_unrealized_pnl(1, 100, 100, 100, 1), 0);
    }

    #[test]
    fn tick_size_scales() {
        assert_eq!(lp_slot_unrealized_pnl(0, 100, 100, 110, 5), 5000);
    }
}

#[cfg(test)]
mod route_funding_tests {
    use super::route_funding;

    #[test]
    fn receipt_beyond_residual_is_clamped_not_reverted() {
        // A receiver owed 1000 against a Residual of only 300 must NOT revert
        // (that would wedge the strict-FIFO ring at the head of apply_fill).
        // It is paid what the Residual can back and the Residual is drained.
        let (col, res) = route_funding(-1000, 500, 300).expect("receipt must not revert");
        assert_eq!(col, 800, "credited only the 300 the Residual could back");
        assert_eq!(res, 0, "Residual fully drawn, never underflowed");
    }

    #[test]
    fn receipt_within_residual_credits_in_full() {
        let (col, res) = route_funding(-1000, 500, 4000).unwrap();
        assert_eq!(col, 1500);
        assert_eq!(res, 3000);
    }

    #[test]
    fn payment_is_clamped_to_collateral() {
        // Payer owes 1000 but holds 400: pays 400, Residual grows by 400.
        let (col, res) = route_funding(1000, 400, 100).unwrap();
        assert_eq!(col, 0);
        assert_eq!(res, 500);
    }

    #[test]
    fn conservation_delta_collateral_equals_negative_delta_residual() {
        for &(owed, col0, res0) in &[
            (-1000i64, 500u64, 300u128),
            (-50, 10, 10_000),
            (1000, 400, 100),
            (777, 10_000, 0),
        ] {
            let (col1, res1) = route_funding(owed, col0, res0).unwrap();
            let d_col = col1 as i128 - col0 as i128;
            let d_res = res1 as i128 - res0 as i128;
            assert_eq!(d_col, -d_res, "funding must conserve value");
        }
    }
}

/// R-1: CROSS-PORTFOLIO intake initial-margin gate. The per-market
/// `assert_intake_initial_margin` below checks only THIS market's resulting IM
/// against the full cross pool, so opening across N markets lets each open see
/// the whole pool as free backing — the portfolio can be opened straight onto the
/// maintenance line with no IM buffer (correlated-gap bad debt then socialises to
/// insurance). This gate closes that: when an order OPENS a NEW cross market, it
/// evaluates the trader's FULL cross portfolio (every existing open leg + the
/// prospective new leg) against the same stress lattice liquidation uses, at the
/// INITIAL-margin ratio.
///
/// It reuses the exact proven machinery from `sweep_collateral`/`partial_withdraw`
/// (`verify_position_pda` + `effective_health_mark` + `assess_margin_unified`) and
/// inherits their omission guarantee: every own leg is PDA-bound to THIS
/// `trader_state`, markets are deduped, and the counted legs must equal
/// `open_positions` — so a caller cannot omit a risky leg to understate the
/// requirement (a short count fails closed). Legs are collected by CONTENT (a
/// program-owned `PositionAccount` whose `trader` matches and which PDA-binds),
/// so the same helper works on the limit path (a clean [market,position] slice)
/// and the taker path (a bag also holding maker/commitment/outbox accounts —
/// maker positions belong to other traders and are naturally excluded).
///
/// Only invoked when the order opens a NEW market slot (the R-1 vector); same-
/// market adds and reduce-only stay on the O(1) `assert_intake_initial_margin`
/// path, so the hot path is unchanged for the common case. Isolated legs carry
/// their own segregated collateral in the snapshot, exactly as the withdraw walk
/// does, and `assess_margin_unified` splits them out.
#[allow(clippy::too_many_arguments)]
fn assert_cross_portfolio_intake_im(
    remaining: &[AccountInfo],
    trader_state_key: &Pubkey,
    trader_pk: &Pubkey,
    program_id: &Pubkey,
    open_positions: u8,
    target_market: &MarketAccount,
    target_market_key: &Pubkey,
    new_side: Side,
    new_resulting_size_lots: u64,
    cross_collateral: u64,
) -> Result<()> {
    let clock = Clock::get()?;
    let now_unix = clock.unix_timestamp.max(0) as u64;
    let current_slot = clock.slot;

    let expected = open_positions as usize;
    let mut snaps: Vec<RiskPosSnap> = Vec::with_capacity(expected + 1);
    let mut market_snaps: Vec<RiskMarketSnap> = Vec::with_capacity(expected + 1);
    let mut market_keys: Vec<Pubkey> = Vec::with_capacity(expected + 1);

    // Collect the trader's OWN open legs from remaining_accounts by content.
    for ai in remaining.iter() {
        if ai.owner != program_id {
            continue;
        }
        let position: state::PositionAccount = {
            let data = match ai.try_borrow_data() {
                Ok(d) => d,
                Err(_) => continue,
            };
            match state::PositionAccount::try_deserialize(&mut &data[..]) {
                Ok(p) => p,
                Err(_) => continue, // not a PositionAccount (market/commitment/outbox/…)
            }
        };
        if position.trader != *trader_pk || position.size_lots == 0 {
            continue; // a maker/other trader's leg, or a flat leg (no IM)
        }
        // Bind to THIS trader_state (blocks a different sub-account's position
        // of the same wallet being substituted to understate risk).
        if verify_position_pda(
            &position.market,
            trader_state_key,
            position.bump,
            &ai.key(),
            program_id,
        )
        .is_err()
        {
            continue;
        }
        // New-market-only: no own leg may sit on the market being opened.
        require!(
            position.market != *target_market_key,
            CloberError::OutOfRange
        );
        require!(
            !market_keys.contains(&position.market),
            CloberError::OutOfRange
        );
        // The leg's market account must be present (program-owned, key match).
        let market_ai = remaining
            .iter()
            .find(|m| *m.key == position.market && m.owner == program_id)
            .ok_or_else(|| error!(CloberError::OutOfRange))?;
        let market_acct: MarketAccount =
            MarketAccount::try_deserialize(&mut &market_ai.try_borrow_data()?[..])?;
        snaps.push(RiskPosSnap {
            market: position.market,
            side: if position.side == 0 {
                Side::Long
            } else {
                Side::Short
            },
            size_lots: position.size_lots,
            entry_price: Ticks(position.entry_price_ticks),
            cum_funding_index_at_entry: position.cum_funding_index(),
            collateral_quote_lots: position.collateral_quote_lots,
        });
        market_snaps.push(RiskMarketSnap {
            market: position.market,
            mark_price: Ticks(effective_health_mark(
                &market_acct,
                now_unix,
                current_slot,
                position.side == 0,
            )?),
            cum_funding_index: market_acct.cum_funding_index,
            // INITIAL margin (buffer above liquidation) — RISK-2, as the walk gates.
            maintenance_margin_bps: market_acct.params.initial_margin_ratio_bps,
            tick_size: market_acct.params.tick_size,
            concentration_threshold_lots: market_acct.params.concentration_threshold_lots,
            concentration_extra_mmr_bps: market_acct.params.concentration_extra_mmr_bps,
            side_oi_lots: oi_side_lots(&market_acct, position.side == 0),
            oi_mmr_slope_bps_per_million_lots: market_acct.params.oi_mmr_slope_bps_per_million_lots,
            oi_mmr_max_extra_bps: market_acct.params.oi_mmr_max_extra_bps,
            paper_profit_haircut_bps: market_acct.paper_profit_haircut_bps,
        });
        market_keys.push(position.market);
    }

    // Omission guarantee: every open cross leg must be accounted for.
    require!(market_keys.len() == expected, CloberError::OutOfRange);

    // Append the prospective new leg on the target market (cross ⇒ backed by the
    // shared pool, so collateral_quote_lots = 0 in the snapshot).
    snaps.push(RiskPosSnap {
        market: *target_market_key,
        side: new_side,
        size_lots: new_resulting_size_lots,
        entry_price: Ticks(target_market.mark_price_ticks),
        cum_funding_index_at_entry: target_market.cum_funding_index,
        collateral_quote_lots: 0,
    });
    market_snaps.push(RiskMarketSnap {
        market: *target_market_key,
        mark_price: Ticks(effective_health_mark(
            target_market,
            now_unix,
            current_slot,
            new_side == Side::Long,
        )?),
        cum_funding_index: target_market.cum_funding_index,
        maintenance_margin_bps: target_market.params.initial_margin_ratio_bps,
        tick_size: target_market.params.tick_size,
        concentration_threshold_lots: target_market.params.concentration_threshold_lots,
        concentration_extra_mmr_bps: target_market.params.concentration_extra_mmr_bps,
        side_oi_lots: oi_side_lots(target_market, new_side == Side::Long),
        oi_mmr_slope_bps_per_million_lots: target_market.params.oi_mmr_slope_bps_per_million_lots,
        oi_mmr_max_extra_bps: target_market.params.oi_mmr_max_extra_bps,
        paper_profit_haircut_bps: target_market.paper_profit_haircut_bps,
    });
    market_keys.push(*target_market_key);

    let scenarios = default_scenarios_fn(&market_keys);
    let assessment = assess_margin_unified_fn(&snaps, &market_snaps, &scenarios, cross_collateral)?;
    require!(
        assessment.is_healthy,
        CloberError::InsufficientCollateral
    );
    Ok(())
}

/// Intake INITIAL-MARGIN gate. A position opened with no (or
/// insufficient) collateral is a FREE OPTION — nothing to lose to liquidation (bad
/// debt is socialised to insurance), unbounded upside. Settlement cannot
/// enforce initial margin on opens (it cannot reject a committed fill without
/// wedging the FIFO ring), so intake must. This gate rejects, at intake, an
/// order whose RESULTING position on THIS market would exceed the trader's backing
/// collateral at the market's initial-margin ratio.
///
/// Sound-by-construction — never rejects a legitimate order:
///   • Pure REDUCE (opposite side, size ≤ current) is EXEMPT — a reduce only lowers
///     margin, so a depleted / underwater trader can always close.
///   • `pos == None` (no position passed — incl. a first-ever open, or an omitted
///     account) ⇒ treated as a pure open of the FULL order size ⇒ the STRICTEST
///     check ⇒ omitting the account can never BYPASS the gate; only a genuine,
///     PDA-verified opposite-side position earns the reduce exemption.
///   • `im_bps == 0` ⇒ the market opted out of initial margin ⇒ no gate.
///
/// Residuals (documented, not fund-loss): this is a per-market check — a cross
/// trader over-leveraged ACROSS markets is caught by liquidation, not here; and a
/// resting limit that opens as a MAKER is gated at placement (reservation), because
/// the maker-side open at settlement cannot be rejected. `backing_collateral` is the
/// caller-selected pool: the position's own collateral for an ISOLATED position,
/// else the cross pool (`trader_state`), matching where margin actually lives.
fn assert_intake_initial_margin(
    side: u8,
    order_size_lots: u64,
    limit_ticks: u64,
    im_bps: u32,
    tick_size: u64,
    backing_collateral: u64,
    pos: Option<(u8, u64)>,
) -> Result<()> {
    if im_bps == 0 {
        return Ok(());
    }
    let resulting_size = match pos {
        None => order_size_lots,
        Some((pos_side, pos_size)) => {
            if pos_side == side {
                pos_size.saturating_add(order_size_lots) // add to same side
            } else if order_size_lots <= pos_size {
                return Ok(()); // pure reduce — always improves margin
            } else {
                order_size_lots - pos_size // flip: net new exposure on `side`
            }
        }
    };
    let notional = (resulting_size as u128)
        .saturating_mul(limit_ticks as u128)
        .saturating_mul(tick_size as u128);
    // Round the initial-margin requirement UP: it is owed to the protocol, so
    // flooring would understate it and let a trader open up to one quote-lot
    // under-margined. `div_ceil` is identical on exact multiples.
    let required_im = notional
        .saturating_mul(im_bps as u128)
        .div_ceil(crate::constants::BPS_DENOM as u128);
    require!(
        (backing_collateral as u128) >= required_im,
        CloberError::InsufficientCollateral
    );
    Ok(())
}

/// Intake OPEN-POSITION-COUNT gate. The cross-margin stress lattice is sized for
/// at most `MAX_POSITIONS_PER_TRADER` positions (that bounds `MAX_STRESS_SCENARIOS`);
/// past it, `assess_margin` rejects the over-long scenario vector and the trader
/// lands in a fail-closed corner — it can no longer pass a portfolio margin check
/// to withdraw or open, only reduce. This gate keeps the common case out of that
/// corner: at intake, an order that would OPEN a NEW position slot on a market
/// where the trader is currently flat is rejected once the trader already holds
/// `MAX_POSITIONS_PER_TRADER` positions.
///
/// Sound-by-construction — never rejects a legitimate reduce:
///   • `pos == Some((_, size > 0))` ⇒ the trader is already open on THIS market
///     (the position PDA is verified against this market by the caller), so the
///     order adds to / reduces / flips an EXISTING slot and cannot raise the slot
///     count ⇒ exempt.
///   • `pos == None` or `Some((_, 0))` ⇒ the trader is flat here ⇒ the order can
///     open a new slot ⇒ gated. Omitting the position only makes the check
///     STRICTER, never a bypass.
///
/// Best-effort by design: the counter increments at SETTLEMENT (a fill going
/// flat→non-flat), which cannot reject, so a burst of new-market opens from below
/// the cap can still race past it. `assess_margin`'s scenario-length check remains
/// the hard backstop that prevents any under-margining in that tail.
fn assert_open_position_budget(open_positions: u8, pos: Option<(u8, u64)>) -> Result<()> {
    let opens_new_slot = match pos {
        None => true,
        Some((_, size)) => size == 0,
    };
    if opens_new_slot {
        require!(
            (open_positions as usize) < crate::constants::MAX_POSITIONS_PER_TRADER,
            CloberError::TooManyOpenPositions
        );
    }
    Ok(())
}

/// H-A (item 4.8, security re-audit 2026-07-10): the shared intake gate every
/// maker-OPEN path must pass before resting an order — factored out so the v3
/// injection handlers (trigger/twap/iceberg/bracket) and `vault_place_order`
/// gate IDENTICALLY to `place_limit_v2_core` / `place_taker_order`. Settlement
/// cannot re-check margin, so a resting order that OPENS exposure must be backed
/// here, or its later fill opens an under-margined position whose loss socializes
/// to insurance. Reduce-only orders are EXEMPT (the maker clamp caps them to
/// reducible size). `pos` = the trader's current (side, size) on this market, or
/// `None` if flat/unavailable (treated as a full open — strictest, matching the
/// canonical `place_limit_v2_core` `Option<position>` semantics). Wired into all 6
/// maker-open paths via `gate_injection_open` (below).
#[allow(clippy::too_many_arguments)]
fn assert_injection_intake(
    side: u8,
    size_lots: u64,
    limit_ticks: u64,
    is_reduce_only: bool,
    im_bps: u32,
    tick_size: u64,
    backing_collateral: u64,
    open_positions: u8,
    pos: Option<(u8, u64)>,
) -> Result<()> {
    if is_reduce_only {
        return Ok(());
    }
    assert_intake_initial_margin(
        side,
        size_lots,
        limit_ticks,
        im_bps,
        tick_size,
        backing_collateral,
        pos,
    )?;
    assert_open_position_budget(open_positions, pos)?;
    Ok(())
}

/// H-A wiring helper: extract `(pos_info, backing)` from an optional PDA-verified
/// position + the trader_state (isolated collateral if the position carries it,
/// else the cross pool), then run `assert_injection_intake`. Mirrors the
/// `place_limit_v2_core` intake block so every v3 maker-open path gates
/// identically. `position == None` ⇒ full-open (strictest), matching the
/// canonical `Option<position>` semantics.
#[allow(clippy::too_many_arguments)]
fn gate_injection_open<'info>(
    market_key: &Pubkey,
    im_bps: u32,
    tick_size: u64,
    trader_state: &AccountLoader<'info, TraderStateAccount>,
    trader_state_key: &Pubkey,
    position: Option<&AccountLoader<'info, state::PositionAccount>>,
    program_id: &Pubkey,
    side: u8,
    size_lots: u64,
    limit_ticks: u64,
    is_reduce_only: bool,
) -> Result<()> {
    let (open_positions, cross_collateral) = {
        let ts = trader_state.load()?;
        (ts.open_positions, ts.collateral_quote_lots)
    };
    let (pos_info, backing) = if let Some(pl) = position {
        let pd = pl.load()?;
        verify_position_pda(market_key, trader_state_key, pd.bump, &pl.key(), program_id)?;
        let backing = if pd.collateral_quote_lots > 0 {
            pd.collateral_quote_lots
        } else {
            cross_collateral
        };
        (Some((pd.side, pd.size_lots)), backing)
    } else {
        (None, cross_collateral)
    };
    assert_injection_intake(
        side,
        size_lots,
        limit_ticks,
        is_reduce_only,
        im_bps,
        tick_size,
        backing,
        open_positions,
        pos_info,
    )
}

#[cfg(test)]
mod ha_injection_intake_tests {
    use super::assert_injection_intake;
    // im_bps=1000 (10%), tick=1: an open of `size` @ `price` needs
    // ceil(size*price*0.10) collateral.
    const IM: u32 = 1000;
    const TS: u64 = 1;

    #[test]
    fn under_margined_open_is_rejected() {
        // open 100 @ 10 → notional 1000, IM required = 100. 99 collateral → reject.
        assert!(assert_injection_intake(0, 100, 10, false, IM, TS, 99, 0, None).is_err());
    }
    #[test]
    fn exactly_at_margin_open_passes() {
        // exactly 100 collateral → ok (boundary).
        assert!(assert_injection_intake(0, 100, 10, false, IM, TS, 100, 0, None).is_ok());
    }
    #[test]
    fn reduce_only_is_exempt_even_with_zero_collateral() {
        // reduce-only bypasses the gate entirely (maker clamp bounds it).
        assert!(assert_injection_intake(0, 100, 10, true, IM, TS, 0, 0, None).is_ok());
    }
    #[test]
    fn reduce_against_existing_position_passes() {
        // sell 40 against a long 100 → pure reduce → ok with no collateral.
        assert!(assert_injection_intake(1, 40, 10, false, IM, TS, 0, 1, Some((0, 100))).is_ok());
    }
    #[test]
    fn zero_im_disables_gate() {
        assert!(assert_injection_intake(0, u64::MAX, u64::MAX, false, 0, TS, 0, 0, None).is_ok());
    }
}

#[cfg(test)]
mod m2_open_position_budget_tests {
    use super::assert_open_position_budget;
    use crate::constants::MAX_POSITIONS_PER_TRADER;

    const CAP: u8 = MAX_POSITIONS_PER_TRADER as u8;

    #[test]
    fn open_below_cap_ok_at_cap_rejected() {
        // Flat on this market (None) ⇒ opening a new slot.
        assert!(assert_open_position_budget(CAP - 1, None).is_ok());
        assert!(assert_open_position_budget(CAP, None).is_err());
        assert!(assert_open_position_budget(CAP + 1, None).is_err());
    }

    #[test]
    fn zero_size_position_counts_as_new_open() {
        // A position account that exists but is flat (size 0) still opens a slot.
        assert!(assert_open_position_budget(CAP, Some((0, 0))).is_err());
        assert!(assert_open_position_budget(CAP - 1, Some((1, 0))).is_ok());
    }

    #[test]
    fn already_open_on_market_is_exempt_even_at_cap() {
        // Live position on THIS market ⇒ add/reduce/flip an existing slot ⇒ exempt,
        // so a trader at the cap can still manage every position they hold.
        assert!(assert_open_position_budget(CAP, Some((0, 100))).is_ok());
        assert!(assert_open_position_budget(CAP + 5, Some((1, 1))).is_ok());
    }
}

#[cfg(test)]
mod m2_intake_margin_tests {
    use super::assert_intake_initial_margin;

    // im_bps = 1000 (10%), tick_size = 1 ⇒ IM(size,price) = size*price*0.10.
    const IM: u32 = 1000;
    const TS: u64 = 1;

    #[test]
    fn zero_collateral_open_rejected() {
        // First open (no position), 100 lots @ 10 ⇒ notional 1000, IM = 100.
        assert!(assert_intake_initial_margin(0, 100, 10, IM, TS, 0, None).is_err());
        assert!(assert_intake_initial_margin(0, 100, 10, IM, TS, 99, None).is_err());
        assert!(assert_intake_initial_margin(0, 100, 10, IM, TS, 100, None).is_ok());
    }

    #[test]
    fn pure_reduce_exempt_even_with_zero_collateral() {
        // Long 100, SELL 100 (opposite, size <= pos) ⇒ reduce ⇒ exempt.
        assert!(assert_intake_initial_margin(1, 100, 10, IM, TS, 0, Some((0, 100))).is_ok());
        // Partial reduce (SELL 40 vs long 100) ⇒ exempt.
        assert!(assert_intake_initial_margin(1, 40, 10, IM, TS, 0, Some((0, 100))).is_ok());
    }

    #[test]
    fn add_same_side_checks_full_resulting_position() {
        // Long 100, BUY 100 ⇒ resulting 200 @ 10 ⇒ IM = 200.
        assert!(assert_intake_initial_margin(0, 100, 10, IM, TS, 199, Some((0, 100))).is_err());
        assert!(assert_intake_initial_margin(0, 100, 10, IM, TS, 200, Some((0, 100))).is_ok());
    }

    #[test]
    fn flip_checks_net_new_exposure() {
        // Long 100, SELL 150 (opposite, size > pos) ⇒ flip to short 50 @ 10 ⇒ IM = 50.
        assert!(assert_intake_initial_margin(1, 150, 10, IM, TS, 49, Some((0, 100))).is_err());
        assert!(assert_intake_initial_margin(1, 150, 10, IM, TS, 50, Some((0, 100))).is_ok());
    }

    #[test]
    fn omitted_position_is_strictest_no_bypass() {
        // Omitting the position (None) forces a full-open check even if the trader
        // actually holds a reducible position ⇒ cannot be used to skip margin.
        assert!(assert_intake_initial_margin(1, 100, 10, IM, TS, 0, None).is_err());
    }

    #[test]
    fn zero_im_market_opts_out() {
        assert!(assert_intake_initial_margin(0, 1_000_000, 1_000_000, 0, TS, 0, None).is_ok());
    }

    #[test]
    fn im_requirement_rounds_up_not_down() {
        // notional = 3 lots @ 3 = 9; IM at 1000 bps = 9*1000/10000 = 0.9.
        // Flooring gives 0 (a free dust open); rounding up requires 1.
        assert!(assert_intake_initial_margin(0, 3, 3, IM, TS, 0, None).is_err());
        assert!(assert_intake_initial_margin(0, 3, 3, IM, TS, 1, None).is_ok());
    }
}

/// Assert `actual` IS the canonical position PDA for
/// `(market, trader_state)`, deriving the canonical bump itself (so it also accepts
/// a fresh, not-yet-initialized position whose stored `bump` is 0 — `verify_position_pda`
/// needs a known bump and so can't be used for the open-via-basket case). `#[inline(never)]`
/// keeps `find_program_address`'s stack out of the caller's BPF frame.
#[inline(never)]
fn require_canonical_position_pda(
    market_key: &Pubkey,
    trader_state_key: &Pubkey,
    actual: &Pubkey,
    program_id: &Pubkey,
) -> Result<()> {
    let (expected, _) = Pubkey::find_program_address(
        &[
            state::PositionAccount::SEED,
            market_key.as_ref(),
            trader_state_key.as_ref(),
        ],
        program_id,
    );
    require_keys_eq!(*actual, expected, CloberError::WrongTrader);
    Ok(())
}

/// Pure-math helper for the underwater loss side of ADL
/// settlement. Returns `(new_position_collateral,
/// new_trader_state_collateral)`.
///
/// Rule:
///   isolated  → debit the per-position bucket, saturating to 0.
///               Cross pool is NEVER touched (preserves I-3 cross-pool
///               insulation). Any unpaid remainder is absorbed by the
///               insurance fund + ADL waterfall — same conservative
///               semantics ADL has always used for the cross path.
///   cross     → debit the cross pool, saturating to 0.
fn route_adl_loss(
    isolated: bool,
    loss_quote_lots: u64,
    pos_collateral: u64,
    trader_state_collateral: u64,
) -> (u64, u64) {
    if isolated {
        (
            pos_collateral.saturating_sub(loss_quote_lots),
            trader_state_collateral,
        )
    } else {
        (
            pos_collateral,
            trader_state_collateral.saturating_sub(loss_quote_lots),
        )
    }
}

/// Pure-math helper for the counter gain side of ADL
/// settlement. Returns `(new_position_collateral,
/// new_trader_state_collateral)`.
///
/// Rule:
///   isolated  → credit the per-position bucket (checked_add).
///   cross     → credit the cross pool (checked_add).
/// Overflow → ArithmeticOverflow.
fn route_adl_gain(
    isolated: bool,
    gain_quote_lots: u64,
    pos_collateral: u64,
    trader_state_collateral: u64,
) -> Result<(u64, u64)> {
    if isolated {
        let new_pos = pos_collateral
            .checked_add(gain_quote_lots)
            .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
        Ok((new_pos, trader_state_collateral))
    } else {
        let new_ts = trader_state_collateral
            .checked_add(gain_quote_lots)
            .ok_or_else(|| error!(CloberError::ArithmeticOverflow))?;
        Ok((pos_collateral, new_ts))
    }
}

/// Track A2: conservation proofs for the ADL collateral-routing helpers that
/// `auto_deleverage` computes its `new_pos_collat` / `new_ts_collat` through.
/// The handler's only compute path for those values IS `route_adl_loss` /
/// `route_adl_gain` (by design — the arithmetic lives here, not inline), so
/// these proofs bind to the shipped ADL path.
#[cfg(kani)]
mod adl_routing_proofs {
    use super::{route_adl_gain, route_adl_loss};

    /// ADL LOSS never mints collateral: the total across the two buckets after a
    /// loss is at most the total before (the loss is socialized to the counter's
    /// gain, never created), and at most `loss` is removed. Real symbol, all u64.
    #[kani::proof]
    fn route_adl_loss_never_mints() {
        let isolated: bool = kani::any();
        let loss: u64 = kani::any();
        let pos: u64 = kani::any();
        let ts: u64 = kani::any();
        let (new_pos, new_ts) = route_adl_loss(isolated, loss, pos, ts);
        let before = pos as u128 + ts as u128;
        let after = new_pos as u128 + new_ts as u128;
        assert!(after <= before); // no minting
        assert!(before - after <= loss as u128); // removes at most the loss
    }

    /// ADL GAIN credits exactly `gain` to one bucket when it does not overflow:
    /// total after == total before + gain. Real symbol, all u64.
    #[kani::proof]
    fn route_adl_gain_credits_exactly() {
        let isolated: bool = kani::any();
        let gain: u64 = kani::any();
        let pos: u64 = kani::any();
        let ts: u64 = kani::any();
        if let Ok((new_pos, new_ts)) = route_adl_gain(isolated, gain, pos, ts) {
            assert!(new_pos as u128 + new_ts as u128 == pos as u128 + ts as u128 + gain as u128);
        }
    }
}

#[cfg(test)]
mod adl_routing_tests {
    use super::*;

    // ─── Loss side ──────────────────────────────────────────────────

    #[test]
    fn loss_isolated_debits_position_bucket() {
        let (pos, ts) = route_adl_loss(true, 100, 500, 10_000);
        assert_eq!(pos, 400);
        assert_eq!(
            ts, 10_000,
            "cross pool must NOT be touched on isolated loss"
        );
    }

    #[test]
    fn loss_isolated_saturates_at_zero_never_touches_cross() {
        // Loss larger than the isolated bucket — saturates to 0.
        // The remainder will be absorbed by the insurance fund via the
        // ADL waterfall. The cross pool is NEVER debited (I-3).
        let (pos, ts) = route_adl_loss(true, 1_000, 500, 10_000);
        assert_eq!(pos, 0);
        assert_eq!(
            ts, 10_000,
            "MUST NOT bleed into cross pool on isolated loss"
        );
    }

    #[test]
    fn loss_cross_debits_cross_pool() {
        let (pos, ts) = route_adl_loss(false, 250, 0, 1_000);
        assert_eq!(pos, 0, "position bucket untouched on cross path");
        assert_eq!(ts, 750);
    }

    #[test]
    fn loss_cross_saturates_at_zero() {
        // Cross-path losses saturate too — ADL is the last resort and
        // must always make progress. The remainder is absorbed by the
        // existing insurance + ADL waterfall.
        let (pos, ts) = route_adl_loss(false, 5_000, 0, 1_000);
        assert_eq!(pos, 0);
        assert_eq!(ts, 0);
    }

    #[test]
    fn loss_zero_amount_is_no_op() {
        let (pos, ts) = route_adl_loss(true, 0, 500, 10_000);
        assert_eq!(pos, 500);
        assert_eq!(ts, 10_000);
        let (pos, ts) = route_adl_loss(false, 0, 500, 10_000);
        assert_eq!(pos, 500);
        assert_eq!(ts, 10_000);
    }

    // ─── Gain side ──────────────────────────────────────────────────

    #[test]
    fn gain_isolated_credits_position_bucket() {
        let (pos, ts) = route_adl_gain(true, 250, 500, 10_000).unwrap();
        assert_eq!(pos, 750);
        assert_eq!(ts, 10_000, "cross pool untouched on isolated gain");
    }

    #[test]
    fn gain_cross_credits_cross_pool() {
        let (pos, ts) = route_adl_gain(false, 250, 500, 10_000).unwrap();
        assert_eq!(pos, 500, "position bucket untouched on cross path");
        assert_eq!(ts, 10_250);
    }

    #[test]
    fn gain_isolated_overflow_errors() {
        let result = route_adl_gain(true, 10, u64::MAX, 0);
        assert!(result.is_err(), "isolated bucket overflow must error");
    }

    #[test]
    fn gain_cross_overflow_errors() {
        let result = route_adl_gain(false, 10, 0, u64::MAX);
        assert!(result.is_err(), "cross pool overflow must error");
    }

    #[test]
    fn gain_zero_amount_is_no_op() {
        let (pos, ts) = route_adl_gain(true, 0, 500, 10_000).unwrap();
        assert_eq!(pos, 500);
        assert_eq!(ts, 10_000);
        let (pos, ts) = route_adl_gain(false, 0, 500, 10_000).unwrap();
        assert_eq!(pos, 500);
        assert_eq!(ts, 10_000);
    }

    // ─── End-to-end consistency: isolated underwater + isolated counter
    //     leaves both cross pools untouched. ────────────────────────

    #[test]
    fn isolated_adl_leaves_both_cross_pools_untouched() {
        let uw_cross_before = 100_000u64;
        let ct_cross_before = 50_000u64;
        let (uw_pos_after, uw_cross_after) = route_adl_loss(
            /* isolated */ true,
            /* loss      */ 800,
            /* pos       */ 1_000,
            /* cross     */ uw_cross_before,
        );
        let (ct_pos_after, ct_cross_after) = route_adl_gain(
            /* isolated */ true,
            /* gain      */ 600,
            /* pos       */ 200,
            /* cross     */ ct_cross_before,
        )
        .unwrap();
        assert_eq!(uw_pos_after, 200);
        assert_eq!(ct_pos_after, 800);
        // Critical I-3 invariant: neither cross pool moved.
        assert_eq!(uw_cross_after, uw_cross_before);
        assert_eq!(ct_cross_after, ct_cross_before);
    }
}

#[cfg(test)]
mod realized_pnl_routing_tests {
    use super::*;

    // §3.2 P4 (M-3): settle_position_funding — the shared per-position funding
    // settlement used by both settle_funding and apply_fill. Verifies (1) the
    // funding anchor advances to the market index, (2) RISK-1 conservation
    // (Δcollateral == −Δresidual: whatever leaves collateral lands in the Residual
    // and vice-versa), and (3) IDEMPOTENCY — a second call once the anchor matches
    // charges nothing (so charging funding in apply_fill never double-charges a
    // position the sequencer also cranked via settle_funding).
    #[test]
    fn settle_position_funding_charges_and_is_idempotent() {
        let zp = <state::PositionAccount as bytemuck::Zeroable>::zeroed();
        let mut pos = state::PositionAccount {
            side: 0,
            size_lots: 100,
            entry_price_ticks: 1000,
            ..zp
        };
        pos.set_cum_funding_index(0);
        let mut ts = <TraderStateAccount as bytemuck::Zeroable>::zeroed();
        ts.collateral_quote_lots = 1_000_000;
        let mut residual: u128 = 1_000_000;
        let market_index: i128 = 1 << 60; // non-zero funding accrued since entry
        let (col0, res0) = (ts.collateral_quote_lots as i128, residual as i128);

        let owed = settle_position_funding(market_index, 1000, 1, &mut pos, &mut ts, &mut residual)
            .unwrap();
        assert_eq!(
            pos.cum_funding_index(),
            market_index,
            "anchor advances to market index"
        );
        assert_ne!(owed, 0, "funding accrued, so a non-zero amount was settled");
        // RISK-1 conservation: collateral and the Residual move by equal/opposite.
        let dcol = ts.collateral_quote_lots as i128 - col0;
        let dres = residual as i128 - res0;
        assert_eq!(dcol, -dres, "Δcollateral == −Δresidual (no mint/burn)");

        // Idempotent: anchor now == market_index, so a second call settles 0.
        let (colp, resp) = (ts.collateral_quote_lots, residual);
        let owed2 =
            settle_position_funding(market_index, 1000, 1, &mut pos, &mut ts, &mut residual)
                .unwrap();
        assert_eq!(
            owed2, 0,
            "already settled to this index → no further charge"
        );
        assert_eq!(
            ts.collateral_quote_lots, colp,
            "no double-charge of collateral"
        );
        assert_eq!(residual, resp, "no double-move of the Residual");
    }

    // Realized PnL settled into the position MUST scale by
    // `tick_size`, matching every other value path (unrealized PnL, funding,
    // fees, liquidation shortfall). Before the fix the factor was dropped, so any
    // market with tick_size>1 mis-scaled settled collateral by 1/tick_size. No
    // prior test covered tick_size>1 (all fixtures pin 1), which is why it shipped.
    #[test]
    fn realized_pnl_scales_with_tick_size_h1() {
        let zeroed = <state::PositionAccount as bytemuck::Zeroable>::zeroed();

        // Long 10 lots @ entry 100, closed by an opposite fill @ 130, tick_size 50.
        // realized = +1 × 10 × (130-100) × 50 = 15_000 quote-lots.
        let mut pos = state::PositionAccount {
            side: 0,
            size_lots: 10,
            entry_price_ticks: 100,
            ..zeroed
        };
        apply_fill_to_position(&mut pos, Side::Short, 10, 130, 0, 50).unwrap();
        assert_eq!(pos.realized_pnl_quote_lots, 15_000);

        // tick_size = 1 reproduces the legacy value (proves no double-count).
        let mut p1 = state::PositionAccount {
            side: 0,
            size_lots: 10,
            entry_price_ticks: 100,
            ..zeroed
        };
        apply_fill_to_position(&mut p1, Side::Short, 10, 130, 0, 1).unwrap();
        assert_eq!(p1.realized_pnl_quote_lots, 300);

        // Short 4 lots @ 200 closed @ 250 on tick_size 10: -1 × 4 × 50 × 10 = -2_000.
        let mut ps = state::PositionAccount {
            side: 1,
            size_lots: 4,
            entry_price_ticks: 200,
            ..zeroed
        };
        apply_fill_to_position(&mut ps, Side::Long, 4, 250, 0, 10).unwrap();
        assert_eq!(ps.realized_pnl_quote_lots, -2_000);
    }

    #[test]
    fn zero_delta_is_no_op() {
        // Cross
        let (iso, cross) = compute_realized_pnl_routing(0, false, 100, 5_000).unwrap();
        assert_eq!(iso, 100);
        assert_eq!(cross, 5_000);
        // Isolated
        let (iso, cross) = compute_realized_pnl_routing(0, true, 100, 5_000).unwrap();
        assert_eq!(iso, 100);
        assert_eq!(cross, 5_000);
    }

    #[test]
    fn gain_credits_isolated_bucket_when_isolated() {
        let (iso, cross) = compute_realized_pnl_routing(250, true, 1_000, 5_000).unwrap();
        assert_eq!(iso, 1_250, "isolated bucket should receive the credit");
        assert_eq!(cross, 5_000, "cross pool untouched on isolated path");
    }

    #[test]
    fn gain_credits_cross_pool_when_not_isolated() {
        let (iso, cross) = compute_realized_pnl_routing(250, false, 1_000, 5_000).unwrap();
        assert_eq!(iso, 1_000, "isolated bucket untouched on cross path");
        assert_eq!(cross, 5_250, "cross pool should receive the credit");
    }

    #[test]
    fn loss_debits_isolated_bucket_when_isolated() {
        let (iso, cross) = compute_realized_pnl_routing(-250, true, 1_000, 5_000).unwrap();
        assert_eq!(iso, 750);
        assert_eq!(cross, 5_000);
    }

    #[test]
    fn loss_truncates_at_zero_on_isolated_path() {
        // Loss larger than isolated balance — saturates to 0, NEVER goes
        // negative and NEVER bleeds into the cross pool. The unpaid
        // remainder is absorbed; the next health check will trip.
        let (iso, cross) = compute_realized_pnl_routing(-2_000, true, 1_000, 5_000).unwrap();
        assert_eq!(iso, 0);
        assert_eq!(
            cross, 5_000,
            "cross pool MUST NOT be touched on isolated loss"
        );
    }

    #[test]
    fn loss_debits_cross_pool_when_not_isolated() {
        let (iso, cross) = compute_realized_pnl_routing(-250, false, 1_000, 5_000).unwrap();
        assert_eq!(iso, 1_000);
        assert_eq!(cross, 4_750);
    }

    #[test]
    fn loss_exceeding_cross_pool_returns_insufficient_collateral() {
        let result = compute_realized_pnl_routing(-6_000, false, 1_000, 5_000);
        assert!(
            result.is_err(),
            "loss > cross pool must error, not go negative"
        );
    }

    // H6: the bankrupt-close path is intercepted by `apply_realized_pnl_direct`
    // via `cross_loss_shortfall` BEFORE it reaches `compute_realized_pnl_routing`
    // (which still errors above — preserving the pure-fn contract).
    #[test]
    fn cross_loss_shortfall_covered_by_pool() {
        // debit fits within the pool → pool drawn down, zero shortfall.
        let (new_cross, shortfall) = cross_loss_shortfall(250, 5_000);
        assert_eq!(new_cross, 4_750);
        assert_eq!(shortfall, 0);
    }

    #[test]
    fn cross_loss_shortfall_bankrupt_saturates_and_surfaces_deficit() {
        // debit exceeds the pool → pool to 0, deficit surfaced for insurance.
        let (new_cross, shortfall) = cross_loss_shortfall(6_000, 5_000);
        assert_eq!(new_cross, 0, "pool must never go negative");
        assert_eq!(
            shortfall, 1_000,
            "deficit beyond collateral is the bad debt"
        );
    }

    #[test]
    fn cross_loss_shortfall_exact_breakeven_is_zero_shortfall() {
        let (new_cross, shortfall) = cross_loss_shortfall(5_000, 5_000);
        assert_eq!(new_cross, 0);
        assert_eq!(shortfall, 0);
    }

    #[test]
    fn cross_loss_shortfall_empty_pool_is_full_deficit() {
        let (new_cross, shortfall) = cross_loss_shortfall(800, 0);
        assert_eq!(new_cross, 0);
        assert_eq!(shortfall, 800);
    }

    // ── ADL fires ONLY on a truly-bankrupt
    // position. `bp` is the equity-zero price, so a mark-solvent position (long
    // above bp / short below bp) must be REJECTED by the gate and routed to
    // ordinary liquidation instead of being wiped at `bp`. Guards the exact helper
    // `auto_deleverage` now requires.
    #[test]
    fn adl_bankruptcy_reached_blocks_mark_solvent_positions() {
        // LONG bankrupt iff health_mark <= bp:
        assert!(
            adl_bankruptcy_reached(0, 90_000, 90_000),
            "long AT bp → bankrupt"
        );
        assert!(
            adl_bankruptcy_reached(0, 89_999, 90_000),
            "long BELOW bp → bankrupt"
        );
        assert!(
            !adl_bankruptcy_reached(0, 90_001, 90_000),
            "long ABOVE bp → mark-solvent → ADL must be BLOCKED (R-1)"
        );
        // SHORT bankrupt iff health_mark >= bp:
        assert!(
            adl_bankruptcy_reached(1, 110_000, 110_000),
            "short AT bp → bankrupt"
        );
        assert!(
            adl_bankruptcy_reached(1, 110_001, 110_000),
            "short ABOVE bp → bankrupt"
        );
        assert!(
            !adl_bankruptcy_reached(1, 109_999, 110_000),
            "short BELOW bp → mark-solvent → ADL must be BLOCKED (R-1)"
        );
    }

    // ── an isolated loss EXCEEDING its bucket now
    // surfaces the uncovered remainder as a shortfall (socialized to insurance via
    // cover_bad_debt) instead of leaving a silent vault deficit. `apply_realized_pnl_
    // delta`'s isolated branch routes through this same Kani-proven `cross_loss_
    // shortfall` (now applied to the per-position bucket), identical to the H6 cross
    // waterfall. This pins the value-conserving math; the apply_fill/apply_lp_fill
    // end-to-end (insurance actually drawn) is an integration follow-up.
    #[test]
    fn isolated_bankruptcy_surfaces_shortfall_for_socialization() {
        let iso_bucket = 5_000u64;
        let (new_iso, shortfall) = cross_loss_shortfall(7_000, iso_bucket);
        assert_eq!(new_iso, 0, "isolated bucket saturates to 0, never negative");
        assert_eq!(
            shortfall, 2_000,
            "uncovered remainder is surfaced for insurance, not a silent vault deficit"
        );
    }

    #[test]
    fn gain_overflowing_isolated_bucket_returns_overflow() {
        let result = compute_realized_pnl_routing(10, true, u64::MAX, 5_000);
        assert!(
            result.is_err(),
            "overflow on the isolated bucket must error"
        );
    }

    #[test]
    fn gain_overflowing_cross_pool_returns_overflow() {
        let result = compute_realized_pnl_routing(10, false, 1_000, u64::MAX);
        assert!(result.is_err(), "overflow on the cross pool must error");
    }

    #[test]
    fn extreme_positive_delta_clamps_to_u64_max_credit() {
        let huge = (u64::MAX as i128) + 1;
        // Credit clamped to u64::MAX. From cross_collateral=0 this means
        // post-credit equals u64::MAX exactly (no overflow).
        let (_iso, cross) = compute_realized_pnl_routing(huge, false, 0, 0).unwrap();
        assert_eq!(cross, u64::MAX);
    }

    #[test]
    fn extreme_negative_delta_clamps_to_u64_max_debit() {
        let huge_neg = -((u64::MAX as i128) + 1);
        // Debit clamped to u64::MAX on the cross path; with cross_collateral
        // = u64::MAX we land at 0 exactly.
        let (_iso, cross) = compute_realized_pnl_routing(huge_neg, false, 0, u64::MAX).unwrap();
        assert_eq!(cross, 0);
    }
}

// ─── V3 monolithic account contexts (merged from former wrappers) ─────────

#[derive(Accounts)]
#[instruction(trigger_id: u8)]
pub struct PlaceTriggerOrder<'info> {
    #[account(mut)]
    pub trader: Signer<'info>,

    // (trader, sub_index) TraderState — existence enforced by
    // AccountLoader; PDA + ownership validated in-handler via verify_trader_state_pda.
    pub trader_state: AccountLoader<'info, TraderStateAccount>,

    pub market: Account<'info, MarketAccount>,

    #[account(
        init,
        payer = trader,
        space = extended_state::TriggerOrderAccount::space(),
        seeds = [
            extended_state::TriggerOrderAccount::SEED,
            market.key().as_ref(),
            trader.key().as_ref(),
            &[trigger_id],
        ],
        bump,
    )]
    pub trigger_order: Account<'info, extended_state::TriggerOrderAccount>,

    pub system_program: Program<'info, System>,
}

#[derive(Accounts)]
pub struct ExecuteTriggerOrder<'info> {
    /// Permissionless caller pays tx fee. Trader pre-authorized at placement.
    pub caller: Signer<'info>,

    pub market: Account<'info, MarketAccount>,

    // H-A: the trigger.trader's (sub_index) TraderState — the permissionless caller
    // supplies it; PDA/ownership bound to `trigger_order.trader` in-handler. Needed
    // for the intake margin gate on an OPENING (non-reduce-only) trigger.
    pub trader_state: AccountLoader<'info, TraderStateAccount>,

    /// CHECK: market_book PDA — disc validated inside handler.
    #[account(
        mut,
        seeds = [book_state::MARKET_BOOK_SEED, market.key().as_ref()],
        bump,
    )]
    pub market_book: UncheckedAccount<'info>,

    #[account(
        mut,
        seeds = [
            extended_state::TriggerOrderAccount::SEED,
            market.key().as_ref(),
            trigger_order.trader.as_ref(),
            &[trigger_order.trigger_id],
        ],
        bump = trigger_order.bump,
    )]
    pub trigger_order: Account<'info, extended_state::TriggerOrderAccount>,

    /// Trader's position — required for reduce-only triggers.
    /// Dropped strict seed (TriggerOrderAccount is
    /// wallet-scoped; Anchor cannot derive trader_state PDA inside
    /// the seeds expression). Identity is enforced by data fields.
    /// Sub-account triggers require a TriggerOrderAccount schema
    /// addition for sub_index before they become useful.
    #[account(
        constraint = position.load()?.market == market.key() @ CloberError::WrongMarket,
        constraint = position.load()?.trader == trigger_order.trader @ CloberError::WrongTrader,
    )]
    pub position: AccountLoader<'info, state::PositionAccount>,

    /// OCO sibling leg. REQUIRED when `trigger_order`
    /// is a bracket leg (`flags & FLAG_HAS_SIBLING`); the handler validates it
    /// is the genuine paired leg and deactivates it so both legs of a bracket
    /// can never both fire. `None` for standalone triggers (backward compatible).
    #[account(mut)]
    pub sibling_trigger: Option<Account<'info, extended_state::TriggerOrderAccount>>,
}

#[derive(Accounts)]
pub struct CancelTriggerOrder<'info> {
    #[account(mut)]
    pub trader: Signer<'info>,

    #[account(
        mut,
        close = trader,
        seeds = [
            extended_state::TriggerOrderAccount::SEED,
            trigger_order.market.as_ref(),
            trigger_order.trader.as_ref(),
            &[trigger_order.trigger_id],
        ],
        bump = trigger_order.bump,
    )]
    pub trigger_order: Account<'info, extended_state::TriggerOrderAccount>,
}

