#[derive(Accounts)]
pub struct UpdateOracleFromPyth<'info> {
    /// Permissionless caller; pays the tx fee. Pyth's PriceUpdateV2 account
    /// is the trust anchor — the caller signing is just to pay for compute.
    pub caller: Signer<'info>,

    #[account(mut)]
    pub market: Account<'info, MarketAccount>,

    #[account(
        seeds = [extended_state::MarketOracleConfigAccount::SEED, market.key().as_ref()],
        bump = oracle_config.bump,
        constraint = oracle_config.market == market.key() @ CloberError::WrongMarket,
    )]
    pub oracle_config: Account<'info, extended_state::MarketOracleConfigAccount>,

    /// CHECK: a Pyth `PriceUpdateV2` account. The handler validates owner ==
    /// PYTH_RECEIVER_PROGRAM_ID, the account discriminator, feed_id, verification
    /// level, and staleness via the in-house `pyth_oracle` parser.
    pub price_update: UncheckedAccount<'info>,

    /// The per-slot price-move cap is MANDATORY on this permissionless
    /// path — were the account optional, any caller could omit it and write
    /// an un-capped move. The envelope is created once via
    /// `set_envelope_config`; markets using the permissionless Pyth-pull path
    /// must have it. (The trusted authority `update_oracle` path keeps it
    /// optional — that caller is already trusted.)
    #[account(
        mut,
        seeds = [extended_state::MarketEnvelopeConfigAccount::SEED, market.key().as_ref()],
        bump = envelope_config.bump,
        constraint = envelope_config.market == market.key() @ CloberError::EnvelopePriceCapInvalid,
    )]
    pub envelope_config: Box<Account<'info, extended_state::MarketEnvelopeConfigAccount>>,
}

/// The trusted Pyth Lazer Solana signer (base58
/// `9gKEEcFzSd1PDYBKWAKZi4Sq4ZCUaVX5oTr8kEjdwsfR`). A payload is only accepted
/// if the Ed25519 precompile verified THIS key over it. Captured from a live
/// Pyth Lazer mainnet message.
pub const TRUSTED_LAZER_SIGNER: [u8; 32] = [
    0x80, 0xef, 0xc1, 0xf4, 0x80, 0xc5, 0x61, 0x5a, 0xf3, 0xfb, 0x67, 0x3d, 0x42, 0x28, 0x7e, 0x99,
    0x3d, 0xa9, 0xfb, 0xc3, 0x50, 0x6b, 0x6e, 0x41, 0xdf, 0xa3, 0x29, 0x50, 0x82, 0x0c, 0x2e, 0x6c,
];

#[derive(Accounts)]
pub struct UpdateOracleFromLazer<'info> {
    /// Permissionless caller; pays the tx fee. The Lazer Ed25519 signature is
    /// the trust anchor, so no market-authority check is required.
    pub caller: Signer<'info>,

    #[account(
        mut,
        seeds = [state::MarketAccount::SEED, market.base_mint.as_ref(), market.quote_mint.as_ref()],
        bump = market.bump,
    )]
    pub market: Box<Account<'info, MarketAccount>>,

    // `mut`: the handler advances `last_lazer_timestamp_us` (the replay nonce).
    #[account(
        mut,
        seeds = [extended_state::MarketOracleConfigAccount::SEED, market.key().as_ref()],
        bump = oracle_config.bump,
        constraint = oracle_config.market == market.key() @ CloberError::WrongMarket,
    )]
    pub oracle_config: Box<Account<'info, extended_state::MarketOracleConfigAccount>>,

    /// The per-slot price-move cap is MANDATORY on this permissionless
    /// path — were the account optional, the caller could omit it and write
    /// an un-capped move. Created once via `set_envelope_config`.
    #[account(
        mut,
        seeds = [extended_state::MarketEnvelopeConfigAccount::SEED, market.key().as_ref()],
        bump = envelope_config.bump,
        constraint = envelope_config.market == market.key() @ CloberError::EnvelopePriceCapInvalid,
    )]
    pub envelope_config: Box<Account<'info, extended_state::MarketEnvelopeConfigAccount>>,

    /// CHECK: the Instructions sysvar — its key is verified to equal
    /// `lazer_oracle::INSTRUCTIONS_SYSVAR_ID` inside the handler, which then
    /// introspects it to confirm the Ed25519 precompile bound the trusted Lazer
    /// signer over the payload.
    pub instructions_sysvar: UncheckedAccount<'info>,
}

