#[cfg(test)]
mod m15_undelegate_gate_tests {
    //! Deterministic coverage of the sequencer-undelegate
    //! gate's pure core. The live er-acceptance round-trip proves ACCEPTANCE of
    //! the real sequencer on the ER; these prove the two REJECTION branches.
    use super::*;

    fn book_pda(market: &Pubkey) -> Pubkey {
        Pubkey::find_program_address(&[book_state::MARKET_BOOK_SEED, market.as_ref()], &crate::ID).0
    }

    #[test]
    fn accepts_real_sequencer_with_canonical_pda() {
        let market = Pubkey::new_unique();
        let seq = Pubkey::new_unique();
        assert!(check_undelegate_binding(
            &book_pda(&market),
            &market,
            book_state::MARKET_BOOK_SEED,
            &seq,
            &seq, // payer == sequencer
        )
        .is_ok());
    }

    #[test]
    fn rejects_non_sequencer_caller() {
        // Canonical book PDA (passes the binding), but payer != sequencer ⇒ the
        // ONLY branch that can fire is Unauthorized.
        let market = Pubkey::new_unique();
        let seq = Pubkey::new_unique();
        let attacker = Pubkey::new_unique();
        assert!(check_undelegate_binding(
            &book_pda(&market),
            &market,
            book_state::MARKET_BOOK_SEED,
            &seq,
            &attacker,
        )
        .is_err());
    }

    #[test]
    fn rejects_substituted_market() {
        // Real book PDA but a DIFFERENT market ⇒ [seed, fake] != book ⇒ WrongMarket
        // fires before the sequencer check, so an attacker can't smuggle a market
        // whose sequencer they control.
        let real_market = Pubkey::new_unique();
        let fake_market = Pubkey::new_unique();
        let seq = Pubkey::new_unique();
        assert!(check_undelegate_binding(
            &book_pda(&real_market),
            &fake_market,
            book_state::MARKET_BOOK_SEED,
            &seq,
            &seq,
        )
        .is_err());
    }

    #[test]
    fn ring_and_outbox_seeds_bind() {
        let market = Pubkey::new_unique();
        let seq = Pubkey::new_unique();
        for seed in [
            matcher::fill_commitment::FILL_COMMIT_SEED,
            matcher::fill_outbox::FILL_OUTBOX_SEED,
        ] {
            let acct = Pubkey::find_program_address(&[seed, market.as_ref()], &crate::ID).0;
            assert!(check_undelegate_binding(&acct, &market, seed, &seq, &seq).is_ok());
            // A book PDA passed under the ring/outbox seed must not validate.
            assert!(
                check_undelegate_binding(&book_pda(&market), &market, seed, &seq, &seq).is_err()
            );
        }
    }
}

#[cfg(test)]
mod oi_crowding_wiring_tests {
    //! 4.4: guards the per-side OI selector that every `RiskMarketSnap` uses to
    //! feed the OI-crowding maintenance surcharge. The surcharge MATH + its
    //! application are proven in `matcher::risk` (unit + Kani); these pin the
    //! side selection that the 13 call sites hand-wire.
    use super::*;

    fn mkt_with_oi(long: u64, short: u64) -> MarketAccount {
        let mut m: MarketAccount = unsafe { core::mem::zeroed() };
        m.oi_long_lots = long;
        m.oi_short_lots = short;
        m
    }

    #[test]
    fn selects_long_oi_for_a_long_leg() {
        let m = mkt_with_oi(700, 300);
        assert_eq!(oi_side_lots(&m, true), 700);
    }

    #[test]
    fn selects_short_oi_for_a_short_leg() {
        let m = mkt_with_oi(700, 300);
        assert_eq!(oi_side_lots(&m, false), 300);
    }
}

#[cfg(kani)]
mod hip3_kani_proofs {
    //! HIP-3 permissionless-market param safety.
    use super::hip3_core_bounds_ok;
    use crate::constants::*;

    /// Anything the permissionless param envelope accepts is conservative:
    /// leverage is capped, maintenance is floored, `IM >= MM` (the
    /// anti-self-liquidation invariant), and the advertised leverage is actually
    /// funded by the initial margin (effective leverage <= HIP3_MAX_LEVERAGE).
    /// Proven for ALL `(max_leverage, mm, im)` — no hostile param combination
    /// slips through, and the `IM * leverage` product is overflow-free.
    #[kani::proof]
    fn hip3_params_are_safe() {
        let max_lev: u32 = kani::any();
        let mm: u32 = kani::any();
        let im: u32 = kani::any();
        if hip3_core_bounds_ok(max_lev, mm, im) {
            assert!((1..=HIP3_MAX_LEVERAGE).contains(&max_lev));
            assert!(mm >= HIP3_MIN_MAINTENANCE_MARGIN_BPS);
            assert!(im >= mm);
            assert!(im >= HIP3_MIN_MAINTENANCE_MARGIN_BPS);
            assert!((im as u64) * (max_lev as u64) >= BPS_DENOM as u64);
        }
    }
}
